window.LESSON={"slug":"robinson","title":"Sir Ken Robinson · Do schools kill creativity? · TED 2006","zhTitle":"学校扼杀了创造力吗？","audio":"../media/robinson-ted.mp3","duration":1148,"segments":[{"n":1,"zh":"开场：三个主题","en":"Three themes","from":0,"to":9,"s":1.9,"e":44.66,"vocab":[{"w":"blown away","ipa":"/bloʊn əˈweɪ/","m":"phr. 大受震撼；被惊艳","ex":"I was blown away by her voice.","exzh":"她的歌声让我大受震撼。"},{"w":"theme","ipa":"/θiːm/","m":"n. 主题","ex":"The theme of the party is the 1980s.","exzh":"派对的主题是八十年代。"},{"w":"extraordinary","ipa":"/ɪkˈstrɔːrdəneri/","m":"adj. 非凡的","ex":"She has an extraordinary memory.","exzh":"她的记忆力非凡。"},{"w":"creativity","ipa":"/ˌkriːeɪˈtɪvəti/","m":"n. 创造力","ex":"Art classes help develop creativity.","exzh":"美术课有助于培养创造力。"},{"w":"play out","ipa":"/pleɪ aʊt/","m":"phr. 发展；展开","ex":"Let's see how things play out.","exzh":"我们看看事情会怎么发展。"}],"gist":{"q":"他说大会贯穿着哪些主题？","opts":["人类的创造力，以及未来的不可预测","足球和音乐","金钱和权力"],"ans":0,"sum":"他幽默地开场，说大会有三个主题：人类非凡的创造力，以及我们完全不知道未来会怎样。"}},{"n":2,"zh":"人人都关心教育","en":"Everybody has an interest in education","from":10,"to":35,"s":45.33,"e":165.56,"vocab":[{"w":"frankly","ipa":"/ˈfræŋkli/","m":"adv. 坦白说","ex":"Frankly, I don't care.","exzh":"坦白说，我不在乎。"},{"w":"vested interest","ipa":"/ˈvestɪd ˈɪntrəst/","m":"n. 切身利益","ex":"Parents have a vested interest in good schools.","exzh":"好学校关系到家长的切身利益。"},{"w":"grasp","ipa":"/ɡræsp/","m":"v. 理解；抓住","ex":"It's hard to grasp the idea.","exzh":"这个概念很难理解。"},{"w":"unpredictability","ipa":"/ˌʌnprɪˌdɪktəˈbɪləti/","m":"n. 不可预测性","ex":"the unpredictability of the weather","exzh":"天气的不可预测性"},{"w":"squander","ipa":"/ˈskwɑːndər/","m":"v. 浪费；挥霍","ex":"Don't squander your talent.","exzh":"别浪费你的天赋。"}],"gist":{"q":"为什么他说“每个人都关心教育”？","opts":["因为教育要带孩子走向一个无法预测的未来","因为教育很赚钱","因为大家都是老师"],"ans":0,"sum":"晚宴上说自己做教育会冷场，但人人都对教育有切身利益：今年入学的孩子 2065 年才退休，没人知道那时世界的样子，而孩子的天赋常被浪费。"}},{"n":3,"zh":"创造力和读写一样重要","en":"Creativity is as important as literacy","from":36,"to":49,"s":166.61,"e":233.33,"vocab":[{"w":"literacy","ipa":"/ˈlɪtərəsi/","m":"n. 读写能力","ex":"Literacy is the key to education.","exzh":"读写能力是教育的关键。"},{"w":"contention","ipa":"/kənˈtenʃn/","m":"n. 观点；论点","ex":"My contention is that he is wrong.","exzh":"我的观点是他错了。"},{"w":"status","ipa":"/ˈsteɪtəs/","m":"n. 地位","ex":"Art should have the same status as math.","exzh":"艺术应与数学享有同等地位。"},{"w":"pay attention","ipa":"/peɪ əˈtenʃn/","m":"phr. 注意；专心","ex":"Please pay attention in class.","exzh":"上课请专心。"},{"w":"fascinated","ipa":"/ˈfæsɪneɪtɪd/","m":"adj. 着迷的","ex":"The kids were fascinated by the show.","exzh":"孩子们看演出看得入迷。"}],"gist":{"q":"他的核心观点是什么？","opts":["创造力和读写能力一样重要","考试越多越好","孩子应该少画画"],"ans":0,"sum":"他认为教育中创造力应与读写同等重要；画上帝的小女孩说“马上就知道了”——孩子充满自信和想象。"}},{"n":4,"zh":"圣诞剧里的三位国王","en":"The Nativity play","from":50,"to":70,"s":236.66,"e":297.81,"vocab":[{"w":"sequel","ipa":"/ˈsiːkwəl/","m":"n. 续集","ex":"The sequel is better than the first film.","exzh":"续集比第一部好看。"},{"w":"thrilled","ipa":"/θrɪld/","m":"adj. 非常兴奋的","ex":"I'm thrilled to hear the news.","exzh":"听到这个消息我非常兴奋。"},{"w":"lead part","ipa":"/liːd pɑːrt/","m":"n. 主角","ex":"She got the lead part in the play.","exzh":"她在剧中演主角。"},{"w":"crammed","ipa":"/kræmd/","m":"adj. 挤满的","ex":"The bus was crammed with people.","exzh":"公交车上挤满了人。"},{"w":"out of sequence","ipa":"/aʊt əv ˈsiːkwəns/","m":"phr. 顺序错乱","ex":"The pages were out of sequence.","exzh":"这些页面顺序乱了。"}],"gist":{"q":"三个“国王”出了什么笑话？","opts":["把礼物顺序弄乱，说成“Frank sent this”","忘了上台","把台词全背错了"],"ans":0,"sum":"四岁的孩子顺序弄乱也不在乎，把 frankincense（乳香）说成“Frank sent this（弗兰克让我送来的）”。"}},{"n":5,"zh":"不怕犯错","en":"Not frightened of being wrong","from":71,"to":87,"s":310.67,"e":370.52,"vocab":[{"w":"take a chance","ipa":"/teɪk ə tʃæns/","m":"phr. 冒险一试","ex":"Take a chance — you might win.","exzh":"冒险试试吧——你可能会赢。"},{"w":"have a go","ipa":"/hæv ə ɡoʊ/","m":"phr. 试一试","ex":"Let me have a go.","exzh":"让我试一试。"},{"w":"original","ipa":"/əˈrɪdʒənl/","m":"adj. 原创的；独创的","ex":"an original idea","exzh":"一个原创的想法"},{"w":"stigmatize","ipa":"/ˈstɪɡmətaɪz/","m":"v. 污名化；使蒙受耻辱","ex":"We shouldn't stigmatize mental illness.","exzh":"我们不应把心理疾病污名化。"},{"w":"grow out of","ipa":"/ɡroʊ aʊt əv/","m":"phr. 长大后失去；长大后不再","ex":"He grew out of his shyness.","exzh":"他长大后不再害羞了。"}],"gist":{"q":"他认为教育对创造力做了什么？","opts":["让孩子害怕犯错，把创造力磨掉了","让创造力越来越强","和创造力无关"],"ans":0,"sum":"孩子敢冒险、不怕错；但学校和公司把错误污名化，结果我们“被教育得失去了创造力”。毕加索说孩子生来都是艺术家。"}},{"n":6,"zh":"莎士比亚也当过孩子","en":"Shakespeare was seven once","from":88,"to":119,"s":372.13,"e":489.6,"vocab":[{"w":"seamless","ipa":"/ˈsiːmləs/","m":"adj. 无缝的；顺畅的","ex":"a seamless transition","exzh":"顺畅的过渡"},{"w":"transition","ipa":"/trænˈzɪʃn/","m":"n. 过渡；转变","ex":"the transition from school to work","exzh":"从学校到职场的转变"},{"w":"annoying","ipa":"/əˈnɔɪɪŋ/","m":"adj. 烦人的","ex":"That noise is so annoying.","exzh":"那噪音太烦人了。"},{"w":"upset","ipa":"/ʌpˈset/","m":"adj. 难过的；不安的","ex":"She was upset about the news.","exzh":"这个消息让她很难过。"},{"w":"anniversary","ipa":"/ˌænɪˈvɜːrsəri/","m":"n. 周年纪念","ex":"our tenth wedding anniversary","exzh":"我们结婚十周年纪念"}],"gist":{"q":"他为什么提到莎士比亚七岁的时候？","opts":["幽默地说明伟人也曾是孩子、也上过普通的课","因为莎士比亚是他的亲戚","因为莎士比亚不喜欢上学"],"ans":0,"sum":"他从莎士比亚故乡搬到洛杉矶，开玩笑说莎士比亚也被老师批“还需努力”；儿子为初恋萨拉在飞机上伤心。"}},{"n":7,"zh":"学科的等级","en":"A hierarchy of subjects","from":120,"to":139,"s":491.48,"e":550.58,"vocab":[{"w":"hierarchy","ipa":"/ˈhaɪərɑːrki/","m":"n. 等级","ex":"a hierarchy of subjects","exzh":"学科的等级"},{"w":"humanities","ipa":"/hjuːˈmænətiz/","m":"n. 人文学科","ex":"She studies the humanities.","exzh":"她学人文学科。"},{"w":"drama","ipa":"/ˈdrɑːmə/","m":"n. 戏剧","ex":"He joined the drama club.","exzh":"他加入了戏剧社。"},{"w":"progressively","ipa":"/prəˈɡresɪvli/","m":"adv. 逐步地","ex":"The pain got progressively worse.","exzh":"疼痛逐渐加重。"},{"w":"waist","ipa":"/weɪst/","m":"n. 腰","ex":"She tied a belt around her waist.","exzh":"她在腰上系了条腰带。"}],"gist":{"q":"全世界的学科等级是怎样的？","opts":["数学和语言在上，艺术在最下面","艺术在最上面","所有学科一样重要"],"ans":0,"sum":"每个教育体系都把数学、语言放在顶端，艺术垫底，舞蹈更是很少每天教；随着孩子长大，我们只教“腰部以上”，最后只剩脑袋。"}},{"n":8,"zh":"教授们活在脑袋里","en":"Living in their heads","from":140,"to":160,"s":551.99,"e":648.31,"vocab":[{"w":"conclude","ipa":"/kənˈkluːd/","m":"v. 得出结论","ex":"What can we conclude from this?","exzh":"从中我们能得出什么结论？"},{"w":"brownie points","ipa":"/ˈbraʊni pɔɪnts/","m":"n. （讨好得来的）加分；好感","ex":"He earned brownie points with his boss.","exzh":"他在老板那儿赢得了好感。"},{"w":"high-water mark","ipa":"/ˌhaɪ ˈwɔːtər mɑːrk/","m":"n. 最高点；巅峰","ex":"This film was the high-water mark of his career.","exzh":"这部电影是他事业的巅峰。"},{"w":"curious","ipa":"/ˈkjʊriəs/","m":"adj. 奇特的；好奇的","ex":"a curious habit","exzh":"一个奇特的习惯"},{"w":"off the beat","ipa":"/ɔːf ðə biːt/","m":"phr. 不合拍","ex":"He was dancing off the beat.","exzh":"他跳舞不合拍。"}],"gist":{"q":"他说公共教育的“目的”看起来像什么？","opts":["培养大学教授","培养舞蹈家","培养运动员"],"ans":0,"sum":"他调侃教授们活在脑袋里，把身体当作运送脑袋的工具；这说明教育只看重学术能力。"}},{"n":9,"zh":"为工业时代设计的教育","en":"Education for industrialism","from":161,"to":186,"s":651.18,"e":761.89,"vocab":[{"w":"academic","ipa":"/ˌækəˈdemɪk/","m":"adj. 学术的","ex":"academic ability","exzh":"学术能力"},{"w":"industrialism","ipa":"/ɪnˈdʌstriəlɪzəm/","m":"n. 工业主义；工业化","ex":"the age of industrialism","exzh":"工业化时代"},{"w":"benign","ipa":"/bɪˈnaɪn/","m":"adj. 善意的；温和的","ex":"benign advice","exzh":"善意的建议"},{"w":"degree","ipa":"/dɪˈɡriː/","m":"n. 学位","ex":"a degree in history","exzh":"历史学学位"},{"w":"inflation","ipa":"/ɪnˈfleɪʃn/","m":"n. 通货膨胀；（价值）膨胀","ex":"academic inflation","exzh":"学历通胀"}],"gist":{"q":"现在的教育体系为什么这样设计？","opts":["为了满足工业化需要，并以学术能力为核心","为了培养艺术家","没有原因"],"ans":0,"sum":"公共教育诞生于 19 世纪工业化时代：有用的学科排在前面，大学按自己的样子设计体系；如今学位越来越不值钱，出现“学历通胀”。"}},{"n":10,"zh":"智力的三个特点","en":"Three things about intelligence","from":187,"to":212,"s":762.06,"e":872.04,"vocab":[{"w":"diverse","ipa":"/daɪˈvɜːrs/","m":"adj. 多样的","ex":"a diverse group of students","exzh":"一群背景多样的学生"},{"w":"dynamic","ipa":"/daɪˈnæmɪk/","m":"adj. 动态的；有活力的","ex":"a dynamic city","exzh":"一座充满活力的城市"},{"w":"discipline","ipa":"/ˈdɪsəplɪn/","m":"n. 学科；纪律","ex":"different academic disciplines","exzh":"不同的学科"},{"w":"multitasking","ipa":"/ˌmʌltiˈtæskɪŋ/","m":"n. 同时处理多项任务","ex":"Multitasking can reduce focus.","exzh":"一心多用会降低专注力。"},{"w":"speak one's mind","ipa":"/spiːk wʌnz maɪnd/","m":"phr. 直言","ex":"She always speaks her mind.","exzh":"她总是有话直说。"}],"gist":{"q":"关于智力他提到哪三个特点？","opts":["多样、动态、独特","固定、单一、遗传","只和数学有关"],"ans":0,"sum":"智力是多样的（视觉、声音、动作……）、动态的（不同方式相互作用，创造力由此而来）、独特的；他还幽默地拿妻子“一心多用”举例。"}},{"n":11,"zh":"吉莉安·琳恩：坐不住的孩子","en":"Gillian Lynne","from":213,"to":233,"s":877.73,"e":939.39,"vocab":[{"w":"distinct","ipa":"/dɪˈstɪŋkt/","m":"adj. 独特的；截然不同的","ex":"Each child is distinct.","exzh":"每个孩子都是独特的。"},{"w":"talent","ipa":"/ˈtælənt/","m":"n. 天赋","ex":"She has a talent for music.","exzh":"她有音乐天赋。"},{"w":"choreographer","ipa":"/ˌkɔːriˈɑːɡrəfər/","m":"n. 编舞者","ex":"a famous choreographer","exzh":"一位著名的编舞家"},{"w":"learning disorder","ipa":"/ˈlɜːrnɪŋ dɪsˈɔːrdər/","m":"n. 学习障碍","ex":"He was tested for a learning disorder.","exzh":"他接受了学习障碍测试。"},{"w":"fidget","ipa":"/ˈfɪdʒɪt/","m":"v. 坐立不安；动来动去","ex":"Stop fidgeting in your seat.","exzh":"别在座位上动来动去。"}],"gist":{"q":"吉莉安·琳恩小时候在学校怎样？","opts":["坐不住、注意力不集中，被认为有学习障碍","成绩第一","非常安静"],"ans":0,"sum":"为了写《顿悟》，他采访了《猫》《歌剧魅影》的编舞家吉莉安·琳恩；她小时候被学校认为有学习障碍，放到今天可能被说成多动症。"}},{"n":12,"zh":"“她是个舞者”","en":"She's a dancer","from":234,"to":259,"s":942.44,"e":1039.1,"vocab":[{"w":"specialist","ipa":"/ˈspeʃəlɪst/","m":"n. 专家；专科医生","ex":"She saw a heart specialist.","exzh":"她看了心脏专科医生。"},{"w":"privately","ipa":"/ˈpraɪvətli/","m":"adv. 私下地","ex":"Can I speak to you privately?","exzh":"我能私下跟你说吗？"},{"w":"audition","ipa":"/ɔːˈdɪʃn/","m":"v./n. 试演；面试（演员）","ex":"She auditioned for the school play.","exzh":"她参加了校园剧的试演。"},{"w":"soloist","ipa":"/ˈsoʊloʊɪst/","m":"n. 独舞者；独唱者","ex":"a soloist with the orchestra","exzh":"乐团的独奏者"},{"w":"medication","ipa":"/ˌmedɪˈkeɪʃn/","m":"n. 药物","ex":"Are you on any medication?","exzh":"你在服用什么药吗？"}],"gist":{"q":"医生发现了什么？","opts":["她不是病了，她是个舞者","她需要吃药","她应该休学"],"ans":0,"sum":"医生打开收音机后离开，她立刻随音乐起舞；医生说“她是个舞者”。她进入舞蹈学校，后来成为著名编舞家——别人可能只会让她吃药安静下来。"}},{"n":13,"zh":"新的人类生态观","en":"A new human ecology","from":260,"to":274,"s":1041.28,"e":1134.48,"vocab":[{"w":"ecology","ipa":"/iˈkɑːlədʒi/","m":"n. 生态","ex":"the ecology of the forest","exzh":"森林的生态"},{"w":"conception","ipa":"/kənˈsepʃn/","m":"n. 观念；概念","ex":"a new conception of education","exzh":"一种新的教育观"},{"w":"commodity","ipa":"/kəˈmɑːdəti/","m":"n. 商品","ex":"Oil is a valuable commodity.","exzh":"石油是一种贵重商品。"},{"w":"flourish","ipa":"/ˈflɜːrɪʃ/","m":"v. 繁荣；茁壮成长","ex":"Plants flourish in the sun.","exzh":"植物在阳光下茁壮成长。"},{"w":"make something of","ipa":"/meɪk ˈsʌmθɪŋ əv/","m":"phr. 有所作为；利用好","ex":"He wants to make something of his life.","exzh":"他想让自己的人生有所作为。"}],"gist":{"q":"他最后呼吁什么？","opts":["重新思考教育，培养孩子的整个人和创造力","增加考试","取消学校"],"ans":0,"sum":"教育像露天采矿一样只开采头脑的一部分；我们需要新的“人类生态观”，看到创造力的丰富与孩子的希望，教育他们整个人去面对未来。"}}],"sentences":[{"id":0,"p":0,"en":"Good morning.","zh":"早上好。","s":1.9,"e":2.63,"w":[[2.02,2.14],[2.16,2.38]]},{"id":1,"p":0,"en":"How are you?","zh":"大家好吗？","s":3.74,"e":4.06,"w":[[3.86,3.94],[4.0,4.08],[4.08,4.16]]},{"id":2,"p":1,"en":"Good.","zh":"很好。","s":4.06,"e":6.0,"w":[[4.18,6.1]]},{"id":3,"p":2,"en":"It's been great, hasn't it?","zh":"这次大会很棒，对吧？","s":6.0,"e":8.76,"w":[[6.12,6.22],[6.26,6.36],[6.4,6.6],[6.62,6.9],[8.45,8.51]]},{"id":4,"p":2,"en":"I've been blown away by the whole thing.","zh":"整个大会让我大开眼界。","s":8.79,"e":10.6,"w":[[8.91,9.01],[9.21,9.33],[9.35,9.53],[9.55,9.75],[9.81,9.89],[9.91,9.97],[9.99,10.15],[10.17,10.35]]},{"id":5,"p":2,"en":"In fact, I'm leaving.","zh":"事实上，我要走了。","s":10.69,"e":11.76,"w":[[10.81,10.87],[10.89,11.07],[11.15,11.21],[11.27,11.51]]},{"id":6,"p":4,"en":"There have been three themes running through the conference, which are relevant to what I want to talk about.","zh":"这次大会贯穿着三个主题，都和我今天要讲的有关。","s":15.76,"e":23.76,"w":[[18.23,18.33],[18.33,18.41],[18.41,18.53],[18.61,18.79],[18.85,19.21],[19.59,19.83],[19.89,20.09],[20.11,20.17],[20.19,20.75],[21.81,21.97],[21.99,22.18],[22.54,22.86],[22.9,22.94],[22.96,23.06],[23.1,23.12],[23.14,23.24],[23.26,23.3],[23.32,23.48],[23.5,23.7]]},{"id":7,"p":4,"en":"One is the extraordinary evidence of human creativity in all of the presentations that we've had and in all of the people here; just the variety of it and the range of it.","zh":"第一个是人类非凡的创造力，体现在我们听到的每一场演讲里，也体现在在座的每一个人身上；光是它的多样和广度就令人惊叹。","s":23.76,"e":35.22,"w":[[23.88,24.0],[24.02,24.14],[24.18,24.3],[24.6,25.68],[26.24,26.68],[26.74,26.82],[26.88,27.08],[27.14,27.7],[28.56,28.7],[29.22,29.32],[29.34,29.38],[29.4,29.46],[29.48,30.0],[30.08,30.18],[30.2,30.32],[30.36,30.6],[30.94,31.04],[31.08,31.14],[31.18,31.26],[31.26,31.3],[31.3,31.36],[31.38,31.64],[31.68,31.88],[32.98,33.12],[33.74,33.82],[33.84,34.32],[34.38,34.46],[34.48,34.56],[34.62,34.68],[34.68,34.74],[34.78,35.04],[35.04,35.1],[35.14,35.22]]},{"id":8,"p":4,"en":"The second is that it's put us in a place where we have no idea what's going to happen in terms of the future.","zh":"第二个是，它让我们意识到，对于未来会发生什么，我们毫无头绪。","s":35.22,"e":42.06,"w":[[36.4,36.48],[36.54,36.89],[36.99,37.15],[37.23,37.35],[37.41,37.59],[37.67,37.79],[37.81,37.89],[37.93,37.99],[38.01,38.03],[38.07,38.33],[38.33,38.45],[38.47,38.51],[38.57,38.71],[38.77,38.85],[39.03,39.23],[39.25,39.41],[39.43,39.57],[39.57,39.63],[39.65,39.89],[41.09,41.15],[41.19,41.35],[41.35,41.39],[41.39,41.45],[41.47,41.81]]},{"id":9,"p":4,"en":"No idea how this may play out.","zh":"完全不知道事情会怎样发展。","s":42.29,"e":44.66,"w":[[42.41,42.47],[42.65,42.83],[43.47,43.61],[43.63,43.75],[43.81,43.91],[43.99,44.17],[44.23,44.41]]},{"id":10,"p":5,"en":"I have an interest in education.","zh":"我对教育很感兴趣。","s":45.33,"e":46.82,"w":[[45.45,45.47],[45.49,45.59],[45.59,45.65],[45.67,45.95],[45.97,46.03],[46.07,46.57]]},{"id":11,"p":5,"en":"Actually, what I find is, everybody has an interest in education.","zh":"其实我发现，每个人都对教育感兴趣。","s":47.11,"e":51.04,"w":[[47.23,47.53],[47.91,48.03],[48.17,48.19],[48.23,48.43],[48.45,48.53],[48.73,49.25],[49.49,49.75],[49.81,49.89],[49.91,50.21],[50.21,50.27],[50.31,50.79]]},{"id":12,"p":5,"en":"Don't you?","zh":"不是吗？","s":51.29,"e":51.93,"w":[[51.41,51.53],[51.58,51.68]]},{"id":13,"p":5,"en":"I find this very interesting.","zh":"我觉得这一点很有意思。","s":52.68,"e":53.36,"w":[[52.8,52.82],[52.82,52.94],[52.94,53.02],[53.02,53.12],[53.16,53.46]]},{"id":14,"p":5,"en":"If you're at a dinner party, and you say you work in education -- actually, you're not often at dinner parties, frankly.","zh":"如果你去参加晚宴，说自己是做教育的——其实说实话，做教育的人不常被邀请去晚宴。","s":53.36,"e":60.55,"w":[[53.48,53.54],[53.54,54.04],[54.04,54.12],[54.14,54.16],[54.24,54.44],[54.48,54.82],[55.72,55.84],[55.86,55.94],[55.98,56.1],[56.14,56.22],[56.24,56.4],[56.42,56.48],[56.52,57.02],[58.18,58.48],[58.54,58.68],[58.72,58.86],[58.92,59.08],[59.1,59.16],[59.18,59.34],[59.36,59.78],[60.06,60.3]]},{"id":15,"p":7,"en":"If you work in education, you're not asked.","zh":"如果你做教育，别人就不会请你。","s":64.78,"e":66.56,"w":[[64.9,64.98],[65.0,65.08],[65.1,65.24],[65.26,65.3],[65.34,65.64],[65.66,65.78],[65.78,65.9],[66.0,66.31]]},{"id":16,"p":9,"en":"And you're never asked back, curiously.","zh":"奇怪的是，也从来不会再请你第二次。","s":70.29,"e":71.61,"w":[[70.41,70.51],[70.51,70.65],[70.65,70.81],[70.87,71.03],[71.07,71.25],[71.33,71.69]]},{"id":17,"p":9,"en":"That's strange to me.","zh":"这让我觉得很奇怪。","s":71.61,"e":73.94,"w":[[71.73,71.91],[73.39,73.59],[73.59,73.63],[73.65,73.69]]},{"id":18,"p":9,"en":"But if you are, and you say to somebody, you know, they say, \"What do you do?\" and you say you work in education, you can see the blood run from their face.","zh":"但如果你去了，别人问你：“你是做什么的？”你说你做教育，你会看到对方的脸一下子没了血色。","s":74.29,"e":81.16,"w":[[74.41,74.51],[74.53,74.59],[74.63,74.71],[74.77,74.97],[75.49,75.59],[75.59,75.67],[75.73,75.85],[75.89,75.95],[76.01,76.31],[76.33,76.77],[76.77,76.87],[76.87,76.95],[76.97,77.05],[77.09,77.21],[77.25,77.31],[77.31,77.39],[77.41,77.51],[77.79,77.87],[77.89,77.97],[78.03,78.19],[78.37,78.47],[78.49,78.61],[78.63,78.69],[78.73,79.23],[79.37,79.45],[79.45,79.53],[79.57,79.67],[79.69,79.75],[79.87,80.13],[80.35,80.49],[80.55,80.67],[80.69,80.81],[80.83,81.16]]},{"id":19,"p":9,"en":"They're like, \"Oh my God.","zh":"他们心想：“天哪。","s":81.16,"e":82.16,"w":[[81.28,81.44],[81.44,81.52],[81.58,81.66],[81.7,81.82],[81.9,82.12]]},{"id":20,"p":9,"en":"Why me?\"","zh":"为什么偏偏是我？”","s":82.16,"e":82.85,"w":[[82.28,82.48],[82.54,82.6]]},{"id":21,"p":11,"en":"\"My one night out all week.\"","zh":"“我一周就这么一个晚上出来玩。”","s":86.06,"e":87.45,"w":[[86.18,86.3],[86.4,86.5],[86.52,86.72],[86.76,86.88],[86.94,87.02],[87.06,87.2]]},{"id":22,"p":13,"en":"But if you ask about their education, they pin you to the wall, because it's one of those things that goes deep with people, am I right?","zh":"但如果你问起他们自己受的教育，他们就会把你堵在墙角说个没完，因为这是那种触动人心深处的话题，对吧？","s":90.4,"e":96.38,"w":[[90.52,90.62],[90.64,90.7],[90.72,90.8],[90.82,90.96],[91.0,91.24],[91.3,91.48],[91.52,91.88],[91.9,91.98],[92.08,92.28],[92.32,92.4],[92.44,92.5],[92.52,92.58],[92.62,92.82],[93.62,93.8],[93.8,93.88],[93.92,94.02],[94.02,94.06],[94.06,94.22],[94.22,94.38],[94.38,94.48],[94.5,94.66],[94.8,94.96],[95.02,95.16],[95.2,95.52],[95.72,95.79],[95.83,95.85],[95.91,96.13]]},{"id":23,"p":13,"en":"Like religion and money and other things.","zh":"就像宗教、金钱之类的事情一样。","s":96.71,"e":100.2,"w":[[96.83,97.01],[97.09,97.49],[97.61,97.85],[97.99,98.19],[99.47,99.55],[99.59,99.71],[99.73,99.95]]},{"id":24,"p":13,"en":"So I have a big interest in education, and I think we all do.","zh":"所以我对教育很感兴趣，我想我们大家都是。","s":100.57,"e":104.86,"w":[[100.69,100.77],[102.65,102.67],[102.69,102.79],[102.81,102.83],[102.85,102.95],[102.99,103.25],[103.25,103.29],[103.31,103.71],[103.73,103.83],[103.89,103.91],[103.95,104.09],[104.15,104.21],[104.33,104.47],[104.53,104.61]]},{"id":25,"p":13,"en":"We have a huge vested interest in it, partly because it's education that's meant to take us into this future that we can't grasp.","zh":"我们和教育有着巨大的切身利益，部分原因是，教育本该带我们走向这个我们无法把握的未来。","s":105.05,"e":111.15,"w":[[105.17,105.23],[105.29,105.37],[105.39,105.41],[105.47,105.71],[105.75,106.05],[106.05,106.35],[106.35,106.39],[106.39,106.47],[106.93,107.33],[107.37,107.73],[107.77,107.89],[107.93,108.53],[108.57,108.71],[108.73,108.87],[108.89,108.95],[109.01,109.23],[109.23,109.31],[109.35,109.47],[109.49,109.63],[109.71,109.99],[109.99,110.07],[110.11,110.17],[110.21,110.43],[110.52,110.9]]},{"id":26,"p":13,"en":"If you think of it, children starting school this year will be retiring in 2065.","zh":"想想看，今年入学的孩子将在 2065 年退休。","s":111.82,"e":120.32,"w":[[111.94,112.0],[112.02,112.12],[112.16,112.32],[112.34,112.4],[112.42,112.5],[112.56,112.86],[112.94,113.32],[113.38,113.62],[113.88,114.08],[114.2,114.44],[115.52,115.66],[115.7,115.78],[115.98,116.64],[117.26,117.36],[117.5,117.8],[117.9,118.18],[118.26,120.22]]},{"id":27,"p":13,"en":"Nobody has a clue, despite all the expertise that's been on parade for the past four days, what the world will look like in five years' time.","zh":"尽管过去四天里各路专家轮番登场，但没有人知道五年后的世界会是什么样子。","s":120.32,"e":127.54,"w":[[120.44,120.74],[120.84,120.98],[121.02,121.04],[121.08,121.3],[121.94,122.24],[122.28,122.38],[122.38,122.44],[122.48,123.02],[123.04,123.2],[123.22,123.38],[123.42,123.52],[123.62,123.98],[124.0,124.06],[124.08,124.14],[124.16,124.38],[124.42,124.58],[124.62,124.94],[125.65,125.79],[125.81,125.89],[125.91,126.05],[126.05,126.15],[126.17,126.27],[126.29,126.45],[126.47,126.53],[126.59,126.85],[126.87,127.03],[127.07,127.29]]},{"id":28,"p":13,"en":"And yet, we're meant to be educating them for it.","zh":"可我们却要为那样的世界教育他们。","s":127.91,"e":129.78,"w":[[128.03,128.11],[128.13,128.25],[128.27,128.39],[128.39,128.51],[128.53,128.57],[128.59,128.65],[128.71,129.15],[129.15,129.25],[129.29,129.41],[129.45,129.53]]},{"id":29,"p":13,"en":"So the unpredictability, I think, is extraordinary.","zh":"所以我认为，这种不可预测性是非同寻常的。","s":130.17,"e":132.62,"w":[[130.29,130.35],[130.39,130.47],[130.49,131.25],[131.49,131.51],[131.55,131.71],[131.73,131.81],[131.85,132.37]]},{"id":30,"p":14,"en":"And the third part of this is that we've all agreed, nonetheless, on the really extraordinary capacities that children have -- their capacities for innovation.","zh":"第三点是，尽管如此，我们都认同孩子拥有非凡的能力——他们的创新能力。","s":132.77,"e":143.57,"w":[[132.89,132.97],[132.99,133.05],[133.09,133.33],[133.45,133.67],[133.69,133.75],[133.77,133.93],[134.07,134.23],[134.29,134.39],[134.45,134.59],[134.63,134.75],[134.79,135.11],[135.17,135.75],[136.47,136.59],[136.67,136.77],[137.49,137.73],[139.01,139.81],[139.87,140.34],[140.38,140.48],[140.54,140.86],[140.9,141.14],[141.74,141.94],[142.24,142.74],[142.76,142.84],[142.86,143.32]]},{"id":31,"p":14,"en":"I mean, Sirena last night was a marvel, wasn't she?","zh":"我是说，昨晚的瑟琳娜太了不起了，对吧？","s":144.0,"e":146.76,"w":[[144.12,144.14],[144.18,144.28],[144.38,144.74],[144.82,145.02],[145.06,145.26],[145.34,145.44],[145.46,145.48],[145.56,145.9],[146.4,146.64],[146.66,146.72]]},{"id":32,"p":14,"en":"Just seeing what she could do.","zh":"光看她能做到的那些事就够了。","s":146.76,"e":148.21,"w":[[146.88,147.06],[147.22,147.42],[147.44,147.56],[147.6,147.68],[147.72,147.86],[147.9,147.96]]},{"id":33,"p":14,"en":"And she's exceptional, but I think she's not, so to speak, exceptional in the whole of childhood.","zh":"她很特别，但我认为，放在整个童年来看，她并不算多么“例外”。","s":148.52,"e":156.7,"w":[[148.64,148.82],[149.5,149.68],[149.7,150.26],[150.58,150.68],[150.78,150.82],[150.88,151.08],[151.16,151.32],[151.38,151.54],[153.0,153.06],[153.12,153.18],[153.22,153.44],[154.14,154.64],[154.73,154.79],[154.83,154.91],[154.99,155.27],[155.73,155.85],[155.97,156.45]]},{"id":34,"p":14,"en":"What you have there is a person of extraordinary dedication who found a talent.","zh":"我们看到的是一个极其投入、找到了自己天赋的人。","s":156.99,"e":159.77,"w":[[157.11,157.23],[157.25,157.33],[157.37,157.53],[157.55,157.67],[157.69,157.73],[157.77,157.79],[157.83,158.07],[158.07,158.13],[158.15,158.57],[158.59,159.05],[159.05,159.13],[159.15,159.37],[159.39,159.41],[159.45,159.77]]},{"id":35,"p":14,"en":"And my contention is, all kids have tremendous talents, and we squander them, pretty ruthlessly.","zh":"我的观点是：所有孩子都有了不起的天赋，而我们却相当无情地把它们浪费掉了。","s":159.77,"e":165.56,"w":[[160.69,160.79],[160.83,160.95],[160.99,161.41],[161.43,161.51],[161.57,161.67],[161.71,161.91],[161.95,162.07],[162.09,162.43],[162.47,162.83],[162.93,163.05],[163.11,163.17],[163.27,163.63],[163.65,163.77],[164.61,164.83],[164.91,165.31]]},{"id":36,"p":15,"en":"So I want to talk about education, and I want to talk about creativity.","zh":"所以我想谈谈教育，也想谈谈创造力。","s":166.61,"e":169.81,"w":[[166.73,166.77],[166.87,166.89],[166.89,166.99],[167.01,167.05],[167.07,167.17],[167.19,167.31],[167.35,167.79],[168.11,168.23],[168.31,168.33],[168.35,168.47],[168.49,168.53],[168.57,168.71],[168.73,168.93],[168.99,169.56]]},{"id":37,"p":15,"en":"My contention is that creativity now is as important in education as literacy, and we should treat it with the same status.","zh":"我的观点是：如今在教育中，创造力和读写能力一样重要，我们应该给它同样的地位。","s":169.88,"e":178.55,"w":[[170.0,170.1],[170.16,170.58],[170.6,170.66],[170.68,170.78],[170.82,171.42],[171.5,171.74],[172.14,172.32],[172.42,172.52],[172.58,173.18],[173.24,173.32],[173.36,173.92],[174.38,174.54],[174.72,175.14],[176.08,176.2],[176.26,176.32],[176.38,176.56],[176.62,176.84],[176.88,176.96],[177.04,177.14],[177.14,177.22],[177.28,177.6],[177.9,178.3]]},{"id":38,"p":17,"en":"Thank you.","zh":"谢谢。","s":179.68,"e":180.23,"w":[[179.8,179.92],[179.92,179.98]]},{"id":39,"p":19,"en":"That was it, by the way.","zh":"顺便说一句，我讲完了。","s":185.73,"e":186.53,"w":[[185.85,185.95],[185.95,186.05],[186.09,186.17],[186.39,186.47],[186.47,186.53],[186.53,186.61]]},{"id":40,"p":19,"en":"Thank you very much.","zh":"非常感谢。","s":186.53,"e":187.28,"w":[[186.65,186.77],[186.77,186.83],[186.83,186.91],[186.91,187.03]]},{"id":41,"p":21,"en":"So, 15 minutes left.","zh":"好，还剩 15 分钟。","s":189.85,"e":191.62,"w":[[189.97,190.09],[190.39,190.75],[190.77,191.01],[191.05,191.37]]},{"id":42,"p":23,"en":"\"Well, I was born ... \"","zh":"“嗯，我出生在……”","s":194.75,"e":195.62,"w":[[194.87,194.97],[195.01,195.03],[195.05,195.15],[195.21,195.37]]},{"id":43,"p":25,"en":"I heard a great story recently -- I love telling it -- of a little girl who was in a drawing lesson.","zh":"我最近听到一个很棒的故事——我很喜欢讲——说的是一个在上图画课的小女孩。","s":200.0,"e":204.98,"w":[[200.12,200.14],[200.16,200.26],[200.28,200.3],[200.32,200.52],[200.56,200.8],[200.86,201.18],[201.8,201.82],[201.84,201.98],[202.0,202.22],[202.22,202.3],[202.36,202.44],[202.46,202.48],[202.52,202.7],[202.74,203.06],[203.32,203.4],[203.52,203.72],[204.3,204.38],[204.4,204.42],[204.48,204.76],[204.78,205.04]]},{"id":44,"p":25,"en":"She was six, and she was at the back, drawing, and the teacher said this girl hardly ever paid attention, and in this drawing lesson, she did.","zh":"她六岁，坐在教室后面画画，老师说这个女孩平时几乎从不专心听讲，可在这节图画课上，她很专心。","s":204.98,"e":210.79,"w":[[205.1,205.18],[205.2,205.3],[205.36,205.56],[205.68,205.78],[205.8,205.86],[205.86,205.94],[205.96,206.02],[206.04,206.1],[206.1,206.26],[206.34,206.68],[206.72,206.8],[206.96,207.02],[207.08,207.34],[207.38,207.52],[207.54,207.66],[207.88,208.04],[208.08,208.3],[208.3,208.42],[208.46,208.62],[208.64,209.02],[209.42,209.5],[209.52,209.56],[209.56,209.66],[209.7,209.94],[209.96,210.2],[210.26,210.32],[210.38,210.54]]},{"id":45,"p":25,"en":"The teacher was fascinated.","zh":"老师很好奇。","s":211.76,"e":212.66,"w":[[211.88,211.96],[212.0,212.24],[212.28,212.36],[212.4,212.74]]},{"id":46,"p":25,"en":"She went over to her, and she said, \"What are you drawing?\"","zh":"她走过去问：“你在画什么？”","s":212.66,"e":215.16,"w":[[212.78,212.84],[212.86,212.98],[213.0,213.18],[213.22,213.28],[213.28,213.34],[213.34,213.42],[213.44,213.5],[213.56,213.75],[214.25,214.39],[214.39,214.45],[214.45,214.55],[214.57,214.91]]},{"id":47,"p":25,"en":"And the girl said, \"I'm drawing a picture of God.\"","zh":"女孩说：“我在画上帝。”","s":215.87,"e":218.56,"w":[[215.99,216.13],[216.15,216.23],[216.25,216.45],[216.57,216.81],[217.15,217.25],[217.29,217.55],[217.57,217.59],[217.65,217.91],[217.93,217.97],[218.03,218.31]]},{"id":48,"p":25,"en":"And the teacher said, \"But nobody knows what God looks like.\"","zh":"老师说：“可是没有人知道上帝长什么样啊。”","s":219.57,"e":222.52,"w":[[219.69,219.77],[219.77,219.83],[219.87,220.11],[220.17,220.41],[220.87,220.97],[221.03,221.21],[221.23,221.39],[221.43,221.55],[221.61,221.75],[221.81,221.97],[222.01,222.27]]},{"id":49,"p":25,"en":"And the girl said, \"They will in a minute.\"","zh":"女孩说：“马上就知道了。”","s":222.93,"e":233.33,"w":[[223.05,223.13],[223.13,223.19],[223.21,223.37],[223.43,223.63],[223.71,223.79],[223.83,223.93],[223.93,223.99],[224.03,224.05],[224.07,233.08]]},{"id":50,"p":27,"en":"When my son was four in England -- actually, he was four everywhere, to be honest.","zh":"我儿子四岁时在英国——其实说实话，他在哪儿都是四岁。","s":236.66,"e":241.09,"w":[[236.78,236.92],[236.98,237.12],[237.24,237.42],[237.52,237.64],[237.78,238.08],[238.34,238.4],[238.44,238.76],[239.5,239.74],[239.74,239.78],[239.8,239.88],[239.92,240.1],[240.12,240.38],[240.4,240.44],[240.46,240.5],[240.54,240.84]]},{"id":51,"p":29,"en":"If we're being strict about it, wherever he went, he was four that year.","zh":"严格来说，那一年不管他去哪儿，他都是四岁。","s":242.22,"e":245.68,"w":[[242.34,243.45],[243.45,243.55],[243.55,243.69],[243.73,243.95],[243.97,244.19],[244.21,244.25],[244.27,244.51],[244.51,244.57],[244.57,244.75],[244.75,244.79],[244.83,244.93],[244.99,245.13],[245.15,245.27],[245.29,245.43]]},{"id":52,"p":29,"en":"He was in the Nativity play.","zh":"他参加了圣诞耶稣诞生剧的演出。","s":246.11,"e":247.59,"w":[[246.23,246.27],[246.35,246.47],[246.51,246.59],[246.63,246.69],[246.77,247.11],[247.17,247.41]]},{"id":53,"p":29,"en":"Do you remember the story?","zh":"你们还记得那个故事吗？","s":247.59,"e":248.62,"w":[[247.71,247.75],[247.75,247.81],[247.81,248.01],[248.03,248.09],[248.13,248.37]]},{"id":54,"p":31,"en":"No, it was big, it was a big story.","zh":"不，那是个大故事，很大的故事。","s":250.65,"e":251.82,"w":[[250.77,250.83],[250.87,250.91],[250.91,250.97],[250.97,251.11],[251.11,251.15],[251.15,251.23],[251.25,251.27],[251.27,251.37],[251.41,251.57]]},{"id":55,"p":31,"en":"Mel Gibson did the sequel, you may have seen it.","zh":"梅尔·吉布森还拍了续集，你们可能看过。","s":252.55,"e":254.34,"w":[[252.67,252.81],[252.85,253.11],[253.13,253.23],[253.23,253.29],[253.33,253.59],[253.63,253.69],[253.69,253.77],[253.77,253.85],[253.87,254.01],[254.03,254.09]]},{"id":56,"p":33,"en":"\"Nativity II.\"","zh":"《耶稣诞生 2》。","s":256.17,"e":257.02,"w":[[256.29,256.63],[256.67,256.77]]},{"id":57,"p":33,"en":"But James got the part of Joseph, which we were thrilled about.","zh":"詹姆斯演的是约瑟，我们高兴坏了。","s":257.7,"e":261.5,"w":[[257.82,257.94],[259.26,259.6],[259.64,259.76],[259.8,259.86],[259.88,260.08],[260.1,260.16],[260.2,260.58],[260.62,260.76],[260.78,260.84],[260.88,260.96],[260.96,261.18],[261.2,261.48]]},{"id":58,"p":33,"en":"We considered this to be one of the lead parts.","zh":"我们觉得这是主角之一。","s":261.5,"e":263.53,"w":[[261.62,261.68],[261.72,262.02],[262.02,262.12],[262.12,262.18],[262.18,262.22],[262.3,262.4],[262.4,262.44],[262.46,262.52],[262.58,262.78],[262.84,263.28]]},{"id":59,"p":33,"en":"We had the place crammed full of agents in T-shirts: \"James Robinson IS Joseph!\"","zh":"现场挤满了穿着 T 恤的经纪人，T 恤上写着：“詹姆斯·罗宾逊就是约瑟！”","s":264.7,"e":268.51,"w":[[264.82,264.88],[264.9,265.0],[265.0,265.08],[265.08,265.28],[265.32,265.58],[265.62,265.72],[265.72,265.78],[265.84,266.16],[266.18,266.24],[266.28,266.3],[266.44,266.74],[267.04,267.26],[267.28,267.56],[267.68,267.84],[267.9,268.26]]},{"id":60,"p":33,"en":"He didn't have to speak, but you know the bit where the three kings come in?","zh":"他不用说台词，不过你们知道三位国王进场的那一段吧？","s":268.58,"e":272.29,"w":[[268.7,268.74],[268.78,270.02],[270.02,270.1],[270.1,270.14],[270.14,270.36],[270.42,270.52],[270.68,270.74],[270.78,270.86],[270.86,270.92],[270.96,271.04],[271.08,271.2],[271.2,271.26],[271.3,271.46],[271.5,271.76],[271.8,271.92],[271.94,272.04]]},{"id":61,"p":33,"en":"They come in bearing gifts, gold, frankincense and myrrh.","zh":"他们带着礼物进来：黄金、乳香和没药。","s":272.97,"e":275.65,"w":[[273.09,273.19],[273.21,273.33],[273.33,273.41],[273.47,273.75],[273.79,274.05],[274.67,274.89],[274.93,275.47],[275.49,275.57],[275.59,275.75]]},{"id":62,"p":33,"en":"This really happened.","zh":"这是真事。","s":275.65,"e":276.37,"w":[[275.77,275.89],[275.97,276.13],[276.19,276.47]]},{"id":63,"p":33,"en":"We were sitting there, and I think they just went out of sequence, because we talked to the little boy afterward and said, \"You OK with that?\"","zh":"我们坐在台下，我想他们大概是把顺序弄乱了，因为事后我们问那个小男孩：“那样没问题吧？”","s":276.37,"e":282.37,"w":[[276.49,276.55],[276.55,276.63],[276.63,276.87],[276.89,277.05],[277.07,277.15],[277.79,277.81],[277.87,278.03],[278.03,278.11],[278.11,278.25],[278.27,278.41],[278.45,278.55],[278.59,278.63],[278.65,279.05],[280.07,280.29],[280.29,280.33],[280.37,280.51],[280.51,280.55],[280.55,280.61],[280.61,280.75],[280.77,280.87],[280.93,281.17],[281.19,281.27],[281.31,281.45],[282.13,282.21],[282.21,282.25],[282.31,282.39],[282.39,282.47]]},{"id":64,"p":33,"en":"They said, \"Yeah, why?","zh":"他们说：“没问题啊，怎么了？","s":282.37,"e":282.93,"w":[[282.49,282.57],[282.61,282.71],[282.73,282.85],[282.89,282.99]]},{"id":65,"p":33,"en":"Was that wrong?\"","zh":"那样不对吗？”","s":282.93,"e":283.64,"w":[[283.05,283.11],[283.13,283.23],[283.25,283.39]]},{"id":66,"p":33,"en":"They just switched.","zh":"他们只是换了顺序。","s":284.03,"e":284.98,"w":[[284.15,284.23],[284.27,284.39],[284.43,284.73]]},{"id":67,"p":33,"en":"The three boys came in, four-year-olds with tea towels on their heads.","zh":"三个男孩进来了，都是四岁，头上顶着擦碗布。","s":285.39,"e":288.69,"w":[[285.51,285.57],[285.59,285.73],[285.75,285.93],[285.97,286.21],[286.23,286.33],[287.05,287.21],[287.21,287.3],[287.32,287.46],[287.5,287.62],[287.64,287.76],[287.8,288.04],[288.06,288.12],[288.14,288.24],[288.24,288.44]]},{"id":68,"p":33,"en":"They put these boxes down, and the first boy said, \"I bring you gold.\"","zh":"他们把盒子放下，第一个男孩说：“我给你带来了黄金。”","s":288.84,"e":292.45,"w":[[288.96,289.04],[289.06,289.16],[289.18,289.3],[289.32,289.66],[289.7,289.88],[289.88,289.94],[289.94,290.0],[290.02,290.24],[290.26,290.42],[290.5,290.74],[291.4,291.42],[291.48,291.66],[291.7,291.78],[291.82,292.2]]},{"id":69,"p":33,"en":"And the second boy said, \"I bring you myrrh.\"","zh":"第二个男孩说：“我给你带来了没药。”","s":293.04,"e":295.15,"w":[[293.16,293.24],[293.24,293.3],[293.34,293.58],[293.6,293.72],[293.8,294.02],[294.32,294.34],[294.38,294.56],[294.6,294.68],[294.74,295.04]]},{"id":70,"p":33,"en":"And the third boy said, \"Frank sent this.\"","zh":"第三个男孩说：“这是弗兰克让我送来的。”（乳香 frankincense 听起来像“Frank sent this”）","s":295.15,"e":297.81,"w":[[295.9,295.98],[295.98,296.06],[296.08,296.28],[296.32,296.46],[296.52,296.7],[296.9,297.12],[297.18,297.34],[297.36,297.56]]},{"id":71,"p":35,"en":"What these things have in common is that kids will take a chance.","zh":"这些事的共同点是：孩子们敢于冒险。","s":310.67,"e":313.48,"w":[[310.79,310.89],[310.91,311.07],[311.07,311.23],[311.27,311.37],[311.39,311.45],[311.49,311.69],[311.89,311.97],[311.99,312.09],[312.15,312.31],[312.35,312.47],[312.51,312.69],[312.71,312.73],[312.79,313.23]]},{"id":72,"p":35,"en":"If they don't know, they'll have a go.","zh":"不知道的时候，他们就试一试。","s":313.89,"e":316.3,"w":[[314.01,314.07],[314.09,314.19],[314.21,314.41],[314.49,314.73],[315.49,315.69],[315.71,315.85],[315.87,315.89],[315.97,316.05]]},{"id":73,"p":35,"en":"Am I right?","zh":"我说得对吧？","s":317.34,"e":318.03,"w":[[317.46,317.52],[317.52,317.54],[317.64,317.78]]},{"id":74,"p":35,"en":"They're not frightened of being wrong.","zh":"他们不怕出错。","s":318.18,"e":320.07,"w":[[318.3,318.44],[318.46,318.58],[318.66,319.02],[319.02,319.08],[319.12,319.32],[319.36,319.82]]},{"id":75,"p":35,"en":"I don't mean to say that being wrong is the same thing as being creative.","zh":"我不是说犯错就等于有创造力。","s":321.22,"e":324.31,"w":[[321.34,321.36],[321.38,321.5],[321.5,321.6],[321.64,321.68],[321.74,321.86],[321.88,321.98],[322.08,322.3],[322.36,322.7],[322.74,322.8],[322.82,322.88],[322.92,323.12],[323.14,323.28],[323.3,323.36],[323.38,323.56],[323.58,324.06]]},{"id":76,"p":35,"en":"What we do know is, if you're not prepared to be wrong, you'll never come up with anything original -- if you're not prepared to be wrong.","zh":"但我们确实知道，如果你没有准备好犯错，你就永远想不出任何原创的东西——如果你不愿意犯错的话。","s":324.88,"e":332.6,"w":[[325.0,325.08],[325.14,325.2],[325.3,325.38],[325.48,325.64],[325.7,325.84],[325.94,326.04],[326.06,326.2],[326.22,326.32],[326.42,326.94],[327.0,327.08],[327.12,327.18],[327.26,327.7],[328.04,328.2],[328.22,328.4],[328.44,328.6],[328.6,328.66],[328.7,328.82],[328.84,329.14],[329.16,329.5],[330.48,330.56],[330.62,330.8],[330.84,330.96],[331.02,331.45],[331.75,331.83],[331.91,331.99],[332.09,332.35]]},{"id":77,"p":35,"en":"And by the time they get to be adults, most kids have lost that capacity.","zh":"而等到长大成人时，大多数孩子已经失去了这种能力。","s":332.97,"e":336.74,"w":[[333.09,333.33],[333.47,333.61],[333.65,333.71],[333.77,333.95],[333.95,334.05],[334.07,334.17],[334.19,334.25],[334.29,334.33],[334.47,334.83],[334.91,335.11],[335.15,335.35],[335.37,335.49],[335.59,335.81],[335.83,335.97],[336.01,336.49]]},{"id":78,"p":35,"en":"They have become frightened of being wrong.","zh":"他们变得害怕犯错。","s":337.69,"e":339.79,"w":[[337.81,337.97],[338.29,338.41],[338.43,338.67],[338.75,339.13],[339.13,339.19],[339.23,339.45],[339.49,339.79]]},{"id":79,"p":35,"en":"And we run our companies like this.","zh":"我们也是这样经营公司的。","s":339.79,"e":341.31,"w":[[339.91,339.99],[340.01,340.07],[340.13,340.25],[340.29,340.39],[340.45,340.83],[340.85,341.15],[341.17,341.25]]},{"id":80,"p":35,"en":"We stigmatize mistakes.","zh":"我们把错误污名化。","s":341.31,"e":342.9,"w":[[341.43,341.49],[341.57,342.13],[342.17,342.65]]},{"id":81,"p":35,"en":"And we're now running national education systems where mistakes are the worst thing you can make.","zh":"我们现在运行的国家教育体系里，犯错是你能做的最糟糕的事。","s":343.29,"e":348.01,"w":[[343.41,343.49],[343.49,343.63],[343.65,343.85],[344.05,344.29],[344.33,344.61],[344.63,345.09],[345.15,345.51],[345.55,345.71],[345.75,346.32],[346.6,346.74],[346.74,346.82],[346.88,347.1],[347.12,347.26],[347.28,347.36],[347.36,347.48],[347.52,347.76]]},{"id":82,"p":35,"en":"And the result is that we are educating people out of their creative capacities.","zh":"结果就是，我们在通过教育把人们的创造力磨掉。","s":348.76,"e":353.77,"w":[[348.88,349.08],[349.5,349.58],[349.62,349.96],[350.02,350.18],[350.34,350.44],[350.48,350.56],[350.64,350.76],[351.06,351.56],[351.6,351.82],[352.0,352.2],[352.24,352.3],[352.32,352.46],[352.5,352.88],[352.9,353.52]]},{"id":83,"p":36,"en":"Picasso once said this, he said that all children are born artists.","zh":"毕加索曾经说过，所有孩子生来都是艺术家。","s":354.2,"e":358.11,"w":[[354.32,354.68],[354.82,354.98],[355.0,355.16],[355.18,355.34],[355.36,355.42],[355.5,355.64],[355.68,355.78],[356.02,356.16],[356.24,356.54],[356.64,356.76],[356.84,357.14],[357.38,357.86]]},{"id":84,"p":36,"en":"The problem is to remain an artist as we grow up.","zh":"问题在于长大以后如何继续做一个艺术家。","s":358.6,"e":361.26,"w":[[358.72,358.78],[358.82,359.1],[359.12,359.2],[359.24,359.28],[359.3,359.6],[359.64,359.7],[359.78,360.12],[360.26,360.38],[360.44,360.52],[360.58,360.78],[360.87,361.01]]},{"id":85,"p":36,"en":"I believe this passionately, that we don't grow into creativity, we grow out of it.","zh":"我对此深信不疑：我们不是长着长着变得有创造力，而是长着长着失去了创造力。","s":362.09,"e":366.48,"w":[[362.21,362.23],[362.23,362.43],[362.45,362.57],[362.61,363.01],[363.05,363.15],[363.17,363.23],[363.29,363.47],[363.51,363.67],[363.99,364.21],[364.27,364.85],[365.27,365.35],[365.41,365.59],[365.87,366.01],[366.03,366.11],[366.13,366.23]]},{"id":86,"p":36,"en":"Or rather, we get educated out of it.","zh":"或者更准确地说，是被教育磨掉了。","s":366.95,"e":368.88,"w":[[367.07,367.13],[367.17,367.43],[367.43,367.49],[367.55,367.67],[367.93,368.35],[368.39,368.51],[368.51,368.55],[368.55,368.63]]},{"id":87,"p":36,"en":"So why is this?","zh":"为什么会这样呢？","s":369.55,"e":370.52,"w":[[369.67,369.75],[369.81,369.95],[370.01,370.09],[370.11,370.27]]},{"id":88,"p":37,"en":"I lived in Stratford-on-Avon until about five years ago.","zh":"大约五年前，我一直住在埃文河畔斯特拉特福。","s":372.13,"e":374.83,"w":[[372.25,372.27],[372.35,372.53],[372.55,372.61],[372.67,372.99],[372.99,373.07],[373.13,373.33],[373.73,374.03],[374.19,374.37],[374.41,374.63],[374.65,374.79],[374.79,374.89]]},{"id":89,"p":37,"en":"In fact, we moved from Stratford to Los Angeles.","zh":"后来，我们从斯特拉特福搬到了洛杉矶。","s":374.83,"e":376.95,"w":[[374.95,374.99],[375.01,375.15],[375.17,375.23],[375.31,375.53],[375.53,375.64],[375.68,376.06],[376.08,376.12],[376.18,376.3],[376.36,376.7]]},{"id":90,"p":37,"en":"So you can imagine what a seamless transition this was.","zh":"你们可以想象这是多么“无缝”的过渡。","s":377.86,"e":380.57,"w":[[377.98,378.02],[378.06,378.12],[378.12,378.2],[378.22,378.46],[378.48,378.56],[378.58,378.6],[378.68,379.0],[379.0,379.46],[379.9,380.02],[380.06,380.32]]},{"id":91,"p":39,"en":"Actually, we lived in a place called Snitterfield, just outside Stratford, which is where Shakespeare's father was born.","zh":"其实我们住的地方叫斯尼特菲尔德，就在斯特拉特福郊外，莎士比亚的父亲就出生在那里。","s":382.2,"e":387.11,"w":[[382.32,382.54],[382.54,382.58],[382.62,382.74],[382.74,382.8],[382.8,382.82],[382.82,382.98],[383.0,383.18],[383.18,383.72],[384.12,384.24],[384.28,384.62],[384.66,385.04],[385.08,385.2],[385.22,385.3],[385.34,385.48],[385.54,386.04],[386.22,386.52],[386.54,386.64],[386.68,386.86]]},{"id":92,"p":39,"en":"Are you struck by a new thought?","zh":"你们是不是突然想到了什么？","s":388.32,"e":389.44,"w":[[388.44,388.52],[388.52,388.58],[388.62,388.8],[388.86,388.98],[389.0,389.02],[389.02,389.14],[389.2,389.46]]},{"id":93,"p":39,"en":"I was.","zh":"我当时就是。","s":389.44,"e":390.07,"w":[[389.56,389.58],[389.62,389.82]]},{"id":94,"p":39,"en":"You don't think of Shakespeare having a father, do you?","zh":"你从没想过莎士比亚也有父亲，对吧？","s":390.37,"e":392.32,"w":[[390.49,390.57],[390.57,390.69],[390.71,390.83],[390.85,390.89],[390.91,391.29],[391.31,391.53],[391.55,391.57],[391.59,391.87],[391.89,391.97],[391.99,392.07]]},{"id":95,"p":39,"en":"Do you?","zh":"对吧？","s":393.05,"e":393.6,"w":[[393.17,393.23],[393.29,393.35]]},{"id":96,"p":39,"en":"Because you don't think of Shakespeare being a child, do you?","zh":"因为你从没想过莎士比亚也当过孩子，对吧？","s":394.35,"e":396.75,"w":[[394.47,394.61],[394.61,394.67],[394.67,394.79],[394.81,394.93],[394.95,394.99],[395.01,395.39],[395.43,395.61],[395.63,395.65],[395.69,396.07],[396.69,396.75],[396.77,396.83]]},{"id":97,"p":39,"en":"Shakespeare being seven?","zh":"七岁的莎士比亚？","s":396.75,"e":398.0,"w":[[396.87,397.21],[397.21,397.39],[397.49,397.75]]},{"id":98,"p":39,"en":"I never thought of it.","zh":"我从没想过。","s":398.71,"e":399.58,"w":[[398.83,398.85],[398.85,398.99],[399.01,399.19],[399.19,399.25],[399.25,399.33]]},{"id":99,"p":39,"en":"I mean, he was seven at some point.","zh":"我是说，他总有七岁的时候吧。","s":399.81,"e":400.79,"w":[[399.93,399.95],[399.95,400.07],[400.07,400.13],[400.19,400.27],[400.37,400.53],[400.55,400.61],[400.65,400.77],[400.77,400.89]]},{"id":100,"p":39,"en":"He was in somebody's English class, wasn't he?","zh":"他也在某个老师的英语课上，对吧？","s":400.79,"e":403.66,"w":[[400.91,400.95],[400.95,401.01],[401.03,401.11],[401.21,401.59],[401.65,401.91],[401.93,402.17],[402.21,403.37],[403.37,403.41]]},{"id":101,"p":41,"en":"How annoying would that be?","zh":"那得多烦人啊？","s":410.76,"e":411.89,"w":[[410.88,410.98],[411.0,411.28],[411.28,411.4],[411.4,411.52],[411.56,411.64]]},{"id":102,"p":43,"en":"\"Must try harder.\"","zh":"“还需努力。”","s":419.91,"e":420.96,"w":[[420.03,420.17],[420.23,420.39],[420.45,420.71]]},{"id":103,"p":45,"en":"Being sent to bed by his dad, to Shakespeare, \"Go to bed, now!\"","zh":"被他爸爸赶去睡觉，对莎士比亚说：“现在就去睡觉！”","s":425.47,"e":428.55,"w":[[425.59,425.75],[425.79,425.95],[425.99,426.03],[426.07,426.25],[426.29,426.41],[426.43,426.55],[426.59,426.79],[426.91,426.97],[427.01,427.37],[427.39,427.45],[427.53,427.59],[427.63,427.79],[428.03,428.35]]},{"id":104,"p":45,"en":"To William Shakespeare.","zh":"对威廉·莎士比亚这么说。","s":428.55,"e":429.61,"w":[[428.67,428.73],[428.77,428.95],[428.99,429.39]]},{"id":105,"p":45,"en":"\"And put the pencil down!\"","zh":"“把铅笔放下！”","s":429.61,"e":430.74,"w":[[429.73,429.81],[429.83,429.93],[429.95,430.01],[430.03,430.31],[430.33,430.49]]},{"id":106,"p":47,"en":"\"And stop speaking like that.\"","zh":"“别再那样说话了。”","s":431.77,"e":433.02,"w":[[431.89,431.97],[432.01,432.17],[432.21,432.51],[432.53,432.65],[432.65,432.77]]},{"id":107,"p":49,"en":"\"It's confusing everybody.\"","zh":"“大家都被你搞糊涂了。”","s":436.31,"e":438.69,"w":[[437.4,437.54],[437.56,438.06],[438.1,438.44]]},{"id":108,"p":51,"en":"Anyway, we moved from Stratford to Los Angeles, and I just want to say a word about the transition.","zh":"总之，我们从斯特拉特福搬到了洛杉矶，我想说说这次搬家。","s":443.82,"e":451.29,"w":[[443.94,444.24],[447.0,447.08],[447.2,447.6],[447.72,447.88],[447.98,448.4],[448.44,448.52],[448.62,448.76],[448.8,449.18],[449.47,449.57],[449.65,449.67],[449.67,449.77],[449.77,449.85],[449.87,449.91],[450.45,450.57],[450.61,450.63],[450.63,450.73],[450.73,450.87],[450.89,450.95],[450.97,451.35]]},{"id":109,"p":51,"en":"Actually, my son didn't want to come.","zh":"其实我儿子不想来。","s":451.29,"e":452.85,"w":[[451.41,451.59],[451.59,451.69],[451.75,451.93],[452.33,452.51],[452.53,452.67],[452.69,452.73],[452.79,452.95]]},{"id":110,"p":51,"en":"I've got two kids; he's 21 now, my daughter's 16.","zh":"我有两个孩子，儿子现在 21 岁，女儿 16 岁。","s":452.85,"e":455.71,"w":[[452.97,453.07],[453.07,453.19],[453.23,453.35],[453.39,453.67],[453.89,454.05],[454.21,454.43],[454.51,454.61],[454.63,454.79],[454.91,455.01],[455.07,455.33],[455.35,455.63]]},{"id":111,"p":51,"en":"He didn't want to come to Los Angeles.","zh":"他不想来洛杉矶。","s":455.71,"e":457.93,"w":[[455.83,455.87],[455.93,456.13],[456.15,456.29],[456.33,456.39],[456.45,456.67],[457.47,457.53],[457.57,457.71],[457.75,458.03]]},{"id":112,"p":51,"en":"He loved it, but he had a girlfriend in England.","zh":"他其实喜欢洛杉矶，但他在英国有个女朋友。","s":457.93,"e":460.96,"w":[[458.05,458.11],[458.15,458.31],[458.35,458.41],[458.47,458.55],[458.57,458.61],[458.63,458.71],[458.75,458.77],[458.83,459.39],[460.29,460.35],[460.37,460.71]]},{"id":113,"p":51,"en":"This was the love of his life, Sarah.","zh":"那是他一生的挚爱，萨拉。","s":461.97,"e":464.68,"w":[[462.09,462.21],[462.23,462.33],[462.35,462.41],[462.49,462.65],[462.65,462.69],[462.73,462.83],[462.89,463.17],[464.2,464.74]]},{"id":114,"p":51,"en":"He'd known her for a month.","zh":"他认识她才一个月。","s":464.68,"e":465.81,"w":[[464.8,464.9],[464.9,465.06],[465.06,465.12],[465.16,465.22],[465.22,465.24],[465.32,465.56]]},{"id":115,"p":53,"en":"Mind you, they'd had their fourth anniversary, because it's a long time when you're 16.","zh":"不过要知道，他们已经过了“四周年纪念”，因为在 16 岁时，一个月已经很长了。","s":467.48,"e":473.02,"w":[[467.6,467.76],[467.76,467.82],[467.84,467.96],[467.96,468.06],[468.08,468.18],[468.22,468.42],[468.44,468.92],[469.6,471.0],[471.02,471.18],[471.2,471.22],[471.3,471.44],[471.5,471.7],[471.7,471.78],[471.8,471.92],[471.92,472.96]]},{"id":116,"p":53,"en":"He was really upset on the plane.","zh":"他在飞机上非常难过。","s":473.02,"e":474.04,"w":[[473.14,473.18],[473.2,473.3],[473.32,473.46],[473.48,473.74],[473.78,473.82],[473.84,473.9],[473.92,474.14]]},{"id":117,"p":53,"en":"He said, \"I'll never find another girl like Sarah.\"","zh":"他说：“我再也找不到像萨拉那样的女孩了。”","s":474.04,"e":476.19,"w":[[474.16,474.2],[474.24,474.36],[474.42,474.52],[474.52,474.68],[474.74,474.96],[475.0,475.18],[475.2,475.38],[475.4,475.56],[475.62,475.94]]},{"id":118,"p":53,"en":"And we were rather pleased about that, frankly --","zh":"坦白说，我们对此还挺高兴的——","s":476.74,"e":478.41,"w":[[476.86,476.92],[476.94,477.0],[477.04,477.14],[477.14,477.32],[477.34,477.58],[477.6,477.76],[477.78,477.88],[477.9,478.16]]},{"id":119,"p":55,"en":"because she was the main reason we were leaving the country.","zh":"因为她正是我们离开英国的主要原因。","s":478.48,"e":489.6,"w":[[478.6,487.61],[488.05,488.13],[488.15,488.23],[488.25,488.31],[488.33,488.45],[488.51,488.69],[488.71,488.75],[488.77,488.85],[488.85,489.03],[489.03,489.09],[489.09,489.35]]},{"id":120,"p":57,"en":"But something strikes you when you move to America and travel around the world: every education system on earth has the same hierarchy of subjects.","zh":"但当你搬到美国、在世界各地旅行时，你会发现一件事：地球上每一个教育体系，都有同样的学科等级。","s":491.48,"e":502.97,"w":[[496.22,496.34],[496.38,496.62],[496.66,496.98],[497.0,497.06],[497.06,497.14],[497.16,497.24],[497.24,497.38],[497.4,497.46],[497.5,497.86],[498.0,498.12],[498.38,498.6],[498.62,498.82],[498.82,498.88],[498.9,499.14],[499.34,499.52],[499.58,500.08],[500.12,500.36],[500.4,500.48],[500.6,500.88],[500.94,501.06],[501.1,501.18],[501.26,501.54],[501.64,502.14],[502.18,502.22],[502.28,502.72]]},{"id":121,"p":57,"en":"Every one.","zh":"每一个都是。","s":503.54,"e":503.88,"w":[[503.66,503.84],[503.9,503.98]]},{"id":122,"p":57,"en":"Doesn't matter where you go.","zh":"不管你去哪儿。","s":503.88,"e":504.68,"w":[[504.0,504.16],[504.16,504.32],[504.38,504.52],[504.52,504.6],[504.62,504.68]]},{"id":123,"p":57,"en":"You'd think it would be otherwise, but it isn't.","zh":"你会以为会有所不同，但并没有。","s":504.68,"e":506.23,"w":[[504.8,504.9],[504.9,505.04],[505.06,505.1],[505.1,505.2],[505.2,505.24],[505.24,505.56],[505.58,505.66],[505.68,505.74],[505.78,505.98]]},{"id":124,"p":57,"en":"At the top are mathematics and languages, then the humanities.","zh":"最上面是数学和语言，然后是人文学科。","s":506.32,"e":509.57,"w":[[506.44,506.5],[506.52,506.6],[506.64,506.86],[506.94,507.04],[507.06,507.72],[507.76,507.84],[507.86,508.31],[508.87,508.99],[509.01,509.09],[509.15,509.67]]},{"id":125,"p":57,"en":"At the bottom are the arts.","zh":"最底下是艺术。","s":509.57,"e":510.75,"w":[[509.69,509.73],[509.75,509.81],[509.87,510.13],[510.13,510.19],[510.19,510.25],[510.37,510.69]]},{"id":126,"p":57,"en":"Everywhere on earth.","zh":"全世界都是如此。","s":510.75,"e":511.84,"w":[[510.87,511.25],[511.27,511.33],[511.37,511.59]]},{"id":127,"p":57,"en":"And in pretty much every system, too, there's a hierarchy within the arts.","zh":"而且几乎每个体系里，艺术内部也有等级。","s":512.51,"e":517.2,"w":[[512.63,512.73],[512.75,512.81],[512.85,513.05],[513.13,513.35],[513.51,513.67],[513.79,514.07],[514.15,514.35],[515.09,515.49],[515.63,515.65],[515.73,516.19],[516.23,516.41],[516.43,516.51],[516.63,516.95]]},{"id":128,"p":57,"en":"Art and music are normally given a higher status in schools than drama and dance.","zh":"在学校里，美术和音乐的地位通常比戏剧和舞蹈高。","s":517.47,"e":521.3,"w":[[517.59,517.75],[517.79,517.87],[517.91,518.27],[518.33,518.43],[518.47,518.77],[518.81,519.01],[519.05,519.07],[519.11,519.31],[519.35,519.69],[519.73,519.79],[519.87,520.19],[520.21,520.31],[520.37,520.61],[520.65,520.71],[520.73,521.05]]},{"id":129,"p":57,"en":"There isn't an education system on the planet that teaches dance every day to children the way we teach them mathematics.","zh":"地球上没有哪个教育体系，会像教数学那样每天教孩子跳舞。","s":521.73,"e":527.09,"w":[[521.85,521.99],[522.03,522.19],[522.29,522.35],[522.39,522.79],[522.83,523.02],[523.04,523.1],[523.14,523.2],[523.26,523.58],[523.96,524.06],[524.1,524.38],[524.44,524.78],[524.9,525.06],[525.1,525.2],[525.24,525.3],[525.36,525.66],[525.68,525.74],[525.76,525.84],[525.88,525.92],[525.98,526.14],[526.16,526.24],[526.26,526.84]]},{"id":130,"p":57,"en":"Why?","zh":"为什么？","s":527.2,"e":527.77,"w":[[527.32,527.52]]},{"id":131,"p":57,"en":"Why not?","zh":"为什么不呢？","s":528.58,"e":529.37,"w":[[528.7,528.82],[528.9,529.12]]},{"id":132,"p":57,"en":"I think this is rather important.","zh":"我认为这个问题相当重要。","s":529.94,"e":531.31,"w":[[530.06,530.08],[530.1,530.22],[530.22,530.32],[530.34,530.42],[530.46,530.66],[530.68,531.06]]},{"id":133,"p":57,"en":"I think math is very important, but so is dance.","zh":"我认为数学非常重要，但舞蹈也一样。","s":531.4,"e":533.36,"w":[[531.52,531.54],[531.54,531.68],[531.76,531.98],[532.04,532.12],[532.14,532.28],[532.32,532.62],[532.64,532.74],[532.78,532.84],[532.94,533.0],[533.04,533.34]]},{"id":134,"p":57,"en":"Children dance all the time if they're allowed to, we all do.","zh":"只要允许，孩子们时时刻刻都在跳舞，我们所有人都是。","s":533.36,"e":535.57,"w":[[533.48,533.74],[533.78,534.02],[534.08,534.16],[534.16,534.22],[534.24,534.48],[534.5,534.54],[534.56,534.7],[534.7,534.9],[534.92,534.98],[535.02,535.1],[535.14,535.22],[535.26,535.32]]},{"id":135,"p":57,"en":"We all have bodies, don't we?","zh":"我们都有身体，对吧？","s":535.68,"e":537.49,"w":[[535.8,535.86],[535.9,536.0],[536.02,536.16],[536.22,536.62],[537.02,537.16],[537.18,537.24]]},{"id":136,"p":57,"en":"Did I miss a meeting?","zh":"难道我错过了什么会议？","s":538.11,"e":539.2,"w":[[538.23,538.33],[538.39,538.41],[538.43,538.55],[538.59,538.61],[538.65,538.95]]},{"id":137,"p":59,"en":"Truthfully, what happens is, as children grow up, we start to educate them progressively from the waist up.","zh":"说实话，实际情况是，随着孩子长大，我们开始逐步只教育他们腰部以上的部分。","s":542.55,"e":546.52,"w":[[542.67,542.95],[542.95,543.05],[543.09,543.33],[543.37,543.49],[543.53,543.63],[543.69,543.91],[543.93,544.03],[544.03,544.11],[544.15,544.21],[544.27,544.49],[544.53,544.57],[544.63,544.93],[544.93,545.01],[545.05,545.59],[545.61,545.73],[545.73,545.81],[545.85,546.11],[546.15,546.27]]},{"id":138,"p":59,"en":"And then we focus on their heads.","zh":"然后我们就只关注他们的脑袋。","s":547.21,"e":548.84,"w":[[547.33,547.39],[547.41,547.49],[547.51,547.57],[547.63,547.89],[547.95,548.03],[548.05,548.19],[548.25,548.59]]},{"id":139,"p":59,"en":"And slightly to one side.","zh":"而且还稍微偏向一边。","s":549.15,"e":550.58,"w":[[549.27,549.37],[549.41,549.69],[549.73,549.79],[549.85,549.97],[550.01,550.33]]},{"id":140,"p":60,"en":"If you were to visit education as an alien and say \"What's it for, public education?\"","zh":"如果你是一个外星人来考察教育，问：“公共教育是干什么用的？”","s":551.99,"e":556.81,"w":[[552.11,552.19],[552.23,552.31],[552.31,552.42],[552.42,552.5],[552.66,552.94],[553.04,553.54],[553.58,553.66],[553.68,553.74],[553.82,554.08],[554.08,554.16],[554.18,554.28],[554.36,554.6],[554.64,554.72],[554.9,555.14],[555.78,556.0],[556.06,556.56]]},{"id":141,"p":60,"en":"I think you'd have to conclude, if you look at the output, who really succeeds by this, who does everything they should, who gets all the brownie points,","zh":"我想，如果你看看它的产出——谁真正在其中获得成功，谁做了所有该做的事，谁拿到了所有加分，","s":557.12,"e":564.12,"w":[[557.24,557.26],[557.28,557.42],[557.42,557.54],[557.56,557.68],[557.7,557.74],[557.78,558.14],[558.24,558.32],[558.34,558.4],[558.42,558.54],[558.54,558.6],[558.62,558.7],[558.82,559.22],[559.52,559.58],[559.84,560.0],[560.08,560.66],[560.72,560.82],[560.86,561.0],[561.0,561.06],[561.1,561.22],[561.22,561.48],[561.5,561.6],[561.7,561.94],[562.68,562.74],[562.8,562.98],[563.04,563.12],[563.12,563.2],[563.24,563.54],[563.6,563.94]]},{"id":142,"p":60,"en":"who are the winners -- I think you'd have to conclude the whole purpose of public education throughout the world is to produce university professors.","zh":"谁是赢家——我想你一定会得出结论：全世界公共教育的整个目的，就是培养大学教授。","s":564.12,"e":572.65,"w":[[564.24,564.3],[564.3,564.38],[564.38,564.44],[564.5,564.84],[565.66,565.68],[565.7,565.82],[565.84,565.94],[565.98,566.16],[566.22,566.28],[566.32,566.82],[566.84,566.92],[566.94,567.13],[567.21,567.63],[567.65,567.71],[567.75,567.99],[568.05,568.49],[568.51,568.73],[568.75,568.81],[568.85,569.15],[569.57,569.65],[569.69,569.77],[569.81,569.97],[569.97,570.81],[570.87,572.75]]},{"id":143,"p":60,"en":"Isn't it?","zh":"不是吗？","s":572.65,"e":573.22,"w":[[572.77,572.93],[572.93,572.97]]},{"id":144,"p":60,"en":"They're the people who come out the top.","zh":"他们是最后走到顶端的人。","s":573.47,"e":574.69,"w":[[573.59,573.73],[573.75,573.81],[573.85,574.07],[574.07,574.13],[574.19,574.37],[574.39,574.51],[574.53,574.59],[574.63,574.79]]},{"id":145,"p":60,"en":"And I used to be one, so there.","zh":"我以前就是其中之一，就这样。","s":574.69,"e":577.28,"w":[[574.81,574.89],[575.11,575.13],[575.17,575.31],[575.33,575.37],[575.49,575.59],[575.75,575.89],[576.63,576.69],[576.79,577.03]]},{"id":146,"p":62,"en":"And I like university professors, but, you know, we shouldn't hold them up as the high-water mark of all human achievement.","zh":"我喜欢大学教授，但你知道，我们不应该把他们奉为人类所有成就的最高标杆。","s":580.37,"e":587.62,"w":[[581.55,581.63],[581.71,581.73],[581.79,581.98],[582.02,582.36],[582.4,582.78],[582.84,582.92],[582.96,583.02],[583.02,583.12],[583.6,583.66],[583.7,583.94],[583.96,584.16],[584.18,584.28],[584.3,584.42],[584.48,584.56],[585.64,585.72],[586.0,586.22],[586.24,586.48],[586.5,586.7],[586.72,586.78],[586.88,587.0],[587.06,587.24],[587.28,587.68]]},{"id":147,"p":62,"en":"They're just a form of life.","zh":"他们只是一种生命形式。","s":587.62,"e":588.99,"w":[[587.74,587.88],[587.88,588.06],[588.08,588.1],[588.14,588.32],[588.36,588.42],[588.48,588.74]]},{"id":148,"p":62,"en":"Another form of life.","zh":"另一种生命形式。","s":590.08,"e":591.35,"w":[[590.2,590.48],[590.52,590.7],[590.74,590.8],[590.86,591.1]]},{"id":149,"p":62,"en":"But they're rather curious.","zh":"不过他们相当奇特。","s":591.54,"e":592.5,"w":[[591.66,591.76],[591.78,591.94],[591.96,592.14],[592.18,592.52]]},{"id":150,"p":62,"en":"And I say this out of affection for them: there's something curious about professors.","zh":"我这么说是出于对他们的喜爱：教授们身上有种奇特的地方。","s":592.5,"e":595.6,"w":[[592.62,592.7],[592.8,592.82],[592.88,592.98],[593.02,593.14],[593.18,593.26],[593.28,593.32],[593.34,593.68],[593.72,593.8],[593.82,593.92],[594.48,594.62],[594.64,594.82],[594.82,595.04],[595.06,595.24],[595.26,595.66]]},{"id":151,"p":62,"en":"In my experience -- not all of them, but typically -- they live in their heads.","zh":"根据我的经验——不是所有人，但通常——他们活在自己的脑袋里。","s":595.6,"e":598.8,"w":[[595.72,595.78],[595.86,595.98],[596.02,596.38],[596.4,596.5],[596.55,596.65],[596.65,596.69],[596.71,596.79],[596.81,596.89],[596.95,597.31],[597.63,597.73],[597.81,597.97],[597.99,598.05],[598.07,598.19],[598.23,598.55]]},{"id":152,"p":62,"en":"They live up there and slightly to one side.","zh":"他们住在上面那儿，而且稍微偏向一边。","s":599.89,"e":602.54,"w":[[600.01,600.09],[600.11,600.25],[600.31,600.39],[600.47,600.69],[601.25,601.33],[601.39,601.67],[601.71,601.77],[601.85,601.95],[601.99,602.29]]},{"id":153,"p":62,"en":"They're disembodied, you know, in a kind of literal way.","zh":"从某种字面意义上说，他们是“脱离身体”的。","s":603.49,"e":606.17,"w":[[603.61,603.79],[603.79,604.53],[605.03,605.09],[605.11,605.19],[605.21,605.27],[605.29,605.31],[605.37,605.51],[605.53,605.57],[605.61,605.87],[605.91,606.07]]},{"id":154,"p":62,"en":"They look upon their body as a form of transport for their heads.","zh":"他们把身体看作运送脑袋的交通工具。","s":606.17,"e":610.08,"w":[[606.97,607.07],[607.09,607.19],[607.23,607.39],[607.43,607.57],[607.67,607.91],[608.13,608.21],[608.25,608.29],[608.33,608.47],[608.51,608.57],[608.63,609.21],[609.25,609.33],[609.35,609.47],[609.51,609.83]]},{"id":155,"p":64,"en":"Don't they?","zh":"不是吗？","s":616.16,"e":616.89,"w":[[616.28,616.46],[616.48,616.64]]},{"id":156,"p":64,"en":"It's a way of getting their head to meetings.","zh":"身体就是把脑袋送去开会的工具。","s":617.52,"e":619.17,"w":[[617.64,617.74],[617.76,617.78],[617.8,617.88],[617.88,617.94],[617.96,618.16],[618.16,618.26],[618.3,618.42],[618.46,618.52],[618.56,618.92]]},{"id":157,"p":66,"en":"If you want real evidence of out-of-body experiences, by the way, get yourself along to a residential conference of senior academics and pop into the discotheque on the final night.","zh":"顺便说一句，如果你想要“灵魂出窍”的真实证据，就去参加一场资深学者的住宿会议，在最后一晚溜进舞厅看看。","s":625.0,"e":634.5,"w":[[625.12,625.22],[625.28,625.36],[625.4,625.58],[625.78,626.09],[626.27,626.61],[626.63,626.71],[626.75,626.87],[626.91,626.95],[626.99,627.17],[627.21,627.73],[627.77,627.89],[627.91,627.97],[627.99,628.13],[629.01,629.13],[629.17,629.45],[629.51,629.79],[629.85,629.89],[629.93,629.95],[630.03,630.43],[630.49,630.89],[630.91,630.97],[631.01,631.23],[631.27,631.79],[632.53,632.61],[632.67,632.83],[632.87,632.99],[633.01,633.09],[633.13,633.59],[633.59,633.65],[633.67,633.73],[633.77,634.03],[634.05,634.25]]},{"id":158,"p":68,"en":"And there, you will see it.","zh":"在那里，你就能看到。","s":635.53,"e":638.47,"w":[[635.65,635.87],[637.55,637.71],[637.73,637.79],[637.81,637.93],[637.99,638.13],[638.17,638.27]]},{"id":159,"p":68,"en":"Grown men and women writhing uncontrollably, off the beat.","zh":"成年男女不受控制地扭动，完全踩不上节拍。","s":638.47,"e":643.15,"w":[[638.59,638.83],[638.89,639.01],[639.05,639.13],[639.17,639.39],[639.53,639.91],[639.97,640.71],[642.48,642.58],[642.64,642.7],[642.74,642.9]]},{"id":160,"p":70,"en":"Waiting until it ends, so they can go home and write a paper about it.","zh":"等着舞会结束，好回家写一篇关于它的论文。","s":645.94,"e":648.31,"w":[[646.06,646.32],[646.32,646.42],[646.44,646.48],[646.54,646.82],[646.84,646.88],[646.9,646.98],[646.98,647.04],[647.04,647.1],[647.14,647.24],[647.24,647.3],[647.3,647.46],[647.48,647.5],[647.54,647.74],[647.76,647.96],[647.98,648.06]]},{"id":161,"p":72,"en":"Our education system is predicated on the idea of academic ability.","zh":"我们的教育体系建立在“学术能力”这个观念之上。","s":651.18,"e":654.65,"w":[[651.3,651.44],[651.52,651.98],[652.02,652.24],[652.3,652.36],[652.44,653.1],[653.14,653.2],[653.22,653.3],[653.38,653.5],[653.52,653.56],[653.66,654.04],[654.08,654.4]]},{"id":162,"p":72,"en":"And there's a reason.","zh":"这是有原因的。","s":655.04,"e":656.02,"w":[[655.16,655.24],[655.26,655.4],[655.42,655.44],[655.51,655.77]]},{"id":163,"p":72,"en":"Around the world, there were no public systems of education, really, before the 19th century.","zh":"在世界各地，19 世纪以前其实并没有公共教育体系。","s":657.69,"e":661.6,"w":[[657.81,658.05],[658.07,658.13],[658.15,658.37],[658.41,658.51],[658.51,658.61],[658.65,658.73],[658.85,659.11],[659.15,659.39],[659.41,659.45],[659.47,659.91],[659.95,660.13],[660.19,660.55],[660.59,660.67],[660.69,660.97],[660.97,661.03],[661.05,661.35]]},{"id":164,"p":72,"en":"They all came into being to meet the needs of industrialism.","zh":"它们都是为了满足工业化的需要而诞生的。","s":661.97,"e":664.68,"w":[[662.09,662.21],[662.33,662.47],[662.55,662.71],[662.73,662.87],[662.93,663.15],[663.17,663.23],[663.27,663.39],[663.43,663.51],[663.53,663.69],[663.71,663.75],[663.79,664.43]]},{"id":165,"p":72,"en":"So the hierarchy is rooted on two ideas.","zh":"所以这种等级根植于两个观念。","s":665.29,"e":667.41,"w":[[665.41,665.49],[665.71,665.77],[665.87,666.37],[666.39,666.47],[666.53,666.75],[666.77,666.83],[666.93,667.07],[667.21,667.47]]},{"id":166,"p":73,"en":"Number one, that the most useful subjects for work are at the top.","zh":"第一，对工作最有用的学科排在最上面。","s":667.41,"e":671.73,"w":[[667.53,667.73],[667.85,667.99],[668.79,668.93],[669.49,669.57],[669.61,669.81],[669.89,670.15],[670.22,670.56],[670.6,670.68],[670.76,670.98],[671.02,671.08],[671.08,671.14],[671.16,671.22],[671.26,671.48]]},{"id":167,"p":73,"en":"So you were probably steered benignly away from things at school when you were a kid, things you liked, on the grounds you would never get a job doing that.","zh":"所以你小时候在学校，很可能被人好心地劝离了那些你喜欢的事，理由是你永远不可能靠它找到工作。","s":672.08,"e":678.91,"w":[[672.2,672.26],[672.34,672.42],[672.42,672.54],[672.56,672.78],[672.86,673.14],[673.2,673.62],[673.66,673.84],[673.9,674.02],[674.08,674.26],[674.28,674.34],[674.38,674.58],[674.6,674.7],[674.72,674.78],[674.78,674.88],[674.88,674.9],[674.94,675.18],[675.64,675.82],[675.84,675.92],[675.98,676.32],[676.84,676.9],[676.92,677.0],[677.0,677.26],[677.26,677.32],[677.32,677.42],[677.46,677.6],[677.62,677.74],[677.78,677.8],[677.86,678.04],[678.16,678.4],[678.44,678.66]]},{"id":168,"p":73,"en":"Is that right?","zh":"是这样吗？","s":679.22,"e":679.97,"w":[[679.34,679.4],[679.42,679.52],[679.56,679.72]]},{"id":169,"p":73,"en":"\"Don't do music, you're not going to be a musician; don't do art, you won't be an artist.\"","zh":"“别学音乐了，你又不会成为音乐家；别学美术了，你又不会成为艺术家。”","s":680.24,"e":683.53,"w":[[680.36,680.52],[680.54,680.6],[680.68,680.98],[681.04,681.16],[681.16,681.22],[681.22,681.32],[681.32,681.36],[681.36,681.4],[681.44,681.46],[681.46,681.82],[681.88,682.04],[682.06,682.12],[682.3,682.48],[682.5,682.58],[682.58,682.7],[682.7,682.74],[682.78,682.84],[682.9,683.28]]},{"id":170,"p":73,"en":"Benign advice -- now, profoundly mistaken.","zh":"这是好意的建议——但在今天，是大错特错的。","s":684.16,"e":687.74,"w":[[684.28,684.66],[684.68,685.13],[685.51,685.73],[686.41,687.01],[687.05,687.49]]},{"id":171,"p":73,"en":"The whole world is engulfed in a revolution.","zh":"整个世界都卷入了一场革命。","s":688.09,"e":690.1,"w":[[688.21,688.27],[688.31,688.49],[688.51,688.73],[688.75,688.81],[688.83,689.23],[689.25,689.31],[689.35,689.37],[689.39,689.85]]},{"id":172,"p":74,"en":"And the second is academic ability, which has really come to dominate our view of intelligence, because the universities design the system in their image.","zh":"第二个观念是学术能力，它已经主导了我们对智力的看法，因为大学按照自己的模样设计了这个体系。","s":690.31,"e":697.56,"w":[[690.43,690.49],[690.49,690.57],[690.63,690.95],[691.01,691.15],[691.47,691.87],[691.91,692.25],[692.35,692.49],[692.51,692.61],[692.67,692.85],[692.89,693.03],[693.05,693.11],[693.17,693.49],[693.55,693.63],[693.67,693.77],[693.81,693.85],[693.89,694.37],[694.39,694.69],[694.71,694.79],[695.11,695.67],[695.97,696.35],[696.39,696.47],[696.51,696.79],[696.81,696.85],[696.87,697.01],[697.05,697.31]]},{"id":173,"p":74,"en":"If you think of it, the whole system of public education around the world is a protracted process of university entrance.","zh":"想想看，全世界的整个公共教育体系，就是一个漫长的“考大学”过程。","s":697.91,"e":703.05,"w":[[698.03,698.09],[698.13,698.21],[698.23,698.37],[698.39,698.43],[698.43,698.49],[698.51,698.59],[698.61,698.81],[698.89,699.13],[699.15,699.19],[699.23,699.45],[699.49,699.82],[699.84,700.06],[700.06,700.14],[700.14,700.38],[700.72,700.78],[700.82,700.84],[700.88,701.32],[701.42,701.78],[701.82,701.88],[701.96,702.34],[702.4,702.8]]},{"id":174,"p":74,"en":"And the consequence is that many highly talented, brilliant, creative people think they're not, because the thing they were good at at school wasn't valued, or was actually stigmatized.","zh":"结果是，很多极有天赋、聪明、有创造力的人，以为自己不行，因为他们在学校擅长的东西不受重视，甚至被污名化。","s":703.62,"e":713.05,"w":[[703.74,703.82],[703.82,703.88],[703.92,704.28],[704.28,704.36],[704.36,704.46],[704.52,704.66],[704.76,705.02],[705.08,705.52],[705.84,706.22],[706.58,707.0],[707.02,707.3],[707.58,707.76],[707.84,708.0],[708.08,708.3],[709.0,709.26],[709.26,709.32],[709.34,709.48],[709.48,709.58],[709.6,709.72],[709.76,709.9],[709.92,710.04],[710.06,710.14],[710.18,710.44],[710.66,710.92],[710.98,711.38],[711.6,711.66],[711.68,711.78],[711.86,712.18],[712.2,712.8]]},{"id":175,"p":74,"en":"And I think we can't afford to go on that way.","zh":"我认为我们不能再这样下去了。","s":713.42,"e":715.3,"w":[[713.54,713.6],[713.68,713.7],[713.72,713.86],[713.88,713.92],[713.96,714.16],[714.18,714.43],[714.45,714.49],[714.53,714.59],[714.67,714.75],[714.77,714.89],[714.91,715.05]]},{"id":176,"p":75,"en":"In the next 30 years, according to UNESCO, more people worldwide will be graduating through education than since the beginning of history.","zh":"据联合国教科文组织统计，在未来 30 年里，全世界接受教育并毕业的人数，将超过有史以来的总和。","s":715.67,"e":722.96,"w":[[715.79,715.83],[715.87,715.93],[715.97,716.21],[716.23,716.47],[716.53,716.83],[717.01,717.33],[717.33,717.39],[717.45,717.81],[718.15,718.35],[718.41,718.71],[718.85,719.51],[719.89,720.05],[720.05,720.09],[720.13,720.67],[720.69,720.83],[720.83,721.29],[721.35,721.45],[721.51,721.71],[721.71,721.79],[721.81,722.17],[722.27,722.35],[722.39,722.71]]},{"id":177,"p":75,"en":"More people.","zh":"更多的人。","s":723.59,"e":724.4,"w":[[723.71,723.85],[723.89,724.15]]},{"id":178,"p":75,"en":"And it's the combination of all the things we've talked about: technology and its transformational effect on work, and demography and the huge explosion in population.","zh":"这是我们谈到的所有因素共同作用的结果：技术及其对工作的变革性影响，还有人口结构和人口的爆炸式增长。","s":724.45,"e":731.93,"w":[[724.57,724.65],[724.67,724.77],[724.79,724.85],[724.89,725.29],[725.29,725.35],[725.41,725.51],[725.53,725.59],[725.59,725.77],[725.79,725.91],[725.93,726.15],[726.17,726.37],[726.43,726.91],[726.97,727.05],[727.07,727.17],[727.21,727.75],[727.75,727.99],[728.05,728.11],[728.19,728.45],[728.99,729.12],[729.2,729.76],[729.96,730.06],[730.06,730.14],[730.2,730.48],[730.52,731.04],[731.04,731.1],[731.12,731.68]]},{"id":179,"p":76,"en":"Suddenly, degrees aren't worth anything.","zh":"突然之间，学位就不值钱了。","s":732.32,"e":734.81,"w":[[732.44,732.76],[733.08,733.5],[733.64,733.82],[733.92,734.14],[734.22,734.56]]},{"id":180,"p":76,"en":"Isn't that true?","zh":"难道不是吗？","s":735.1,"e":735.91,"w":[[735.22,735.32],[735.34,735.46],[735.5,735.66]]},{"id":181,"p":76,"en":"When I was a student, if you had a degree, you had a job.","zh":"我上学的时候，有学位就有工作。","s":736.82,"e":739.8,"w":[[736.94,737.06],[737.16,737.18],[737.2,737.3],[737.36,737.38],[737.48,737.82],[738.18,738.26],[738.3,738.38],[738.42,738.52],[738.56,738.58],[738.62,738.88],[739.08,739.16],[739.22,739.34],[739.38,739.4],[739.48,739.74]]},{"id":182,"p":76,"en":"If you didn't have a job, it's because you didn't want one.","zh":"如果你没有工作，那是因为你不想要。","s":739.8,"e":742.27,"w":[[739.92,739.98],[740.02,740.1],[740.12,740.34],[740.38,740.52],[740.54,740.56],[740.62,740.84],[740.92,741.04],[741.06,741.3],[741.32,741.38],[741.42,741.66],[741.7,741.84],[741.92,742.02]]},{"id":183,"p":76,"en":"And I didn't want one, frankly.","zh":"坦白说，我当时就不想要。","s":742.46,"e":744.66,"w":[[742.58,742.68],[742.92,742.94],[743.26,743.5],[743.56,743.72],[743.78,743.89],[744.13,744.41]]},{"id":184,"p":78,"en":"But now kids with degrees are often heading home to carry on playing video games, because you need an MA where the previous job required a BA, and now you need a PhD for the other.","zh":"但现在，有学位的孩子常常回家继续打电子游戏，因为以前要本科学历的工作，现在要硕士；以前要硕士的，现在要博士。","s":746.59,"e":756.87,"w":[[746.71,746.83],[746.91,747.23],[747.79,748.09],[748.15,748.59],[748.63,749.05],[749.19,749.29],[749.31,749.49],[749.57,749.81],[749.85,750.01],[750.45,750.51],[750.57,750.73],[750.77,750.83],[750.87,751.07],[751.09,751.27],[751.33,751.63],[752.31,752.55],[752.55,752.63],[752.65,752.75],[752.77,752.85],[752.95,753.05],[753.33,753.51],[753.55,753.65],[753.87,754.19],[754.29,754.47],[754.51,754.85],[754.85,754.87],[754.91,755.09],[755.21,755.29],[755.33,755.49],[755.65,755.73],[755.75,755.85],[755.89,755.91],[755.95,756.29],[756.47,756.55],[756.57,756.63],[756.65,756.77]]},{"id":185,"p":78,"en":"It's a process of academic inflation.","zh":"这是一个学历通胀的过程。","s":756.87,"e":758.72,"w":[[756.99,757.11],[757.13,757.15],[757.19,757.53],[757.55,757.61],[757.67,757.99],[758.05,758.47]]},{"id":186,"p":78,"en":"And it indicates the whole structure of education is shifting beneath our feet.","zh":"它说明整个教育结构正在我们脚下发生变化。","s":758.76,"e":761.89,"w":[[758.88,758.94],[758.96,759.04],[759.1,759.46],[759.48,759.54],[759.56,759.72],[759.76,760.14],[760.14,760.18],[760.22,760.64],[760.66,760.7],[760.74,761.04],[761.06,761.28],[761.34,761.44],[761.46,761.64]]},{"id":187,"p":78,"en":"We need to radically rethink our view of intelligence.","zh":"我们需要彻底重新思考我们对智力的看法。","s":762.06,"e":764.43,"w":[[762.18,762.24],[762.28,762.38],[762.42,762.48],[762.6,762.94],[763.0,763.26],[763.32,763.42],[763.44,763.54],[763.56,763.6],[763.62,764.18]]},{"id":188,"p":79,"en":"We know three things about intelligence.","zh":"关于智力，我们知道三件事。","s":764.48,"e":766.04,"w":[[764.6,764.66],[764.68,764.8],[764.88,765.08],[765.1,765.3],[765.32,765.5],[765.54,766.0]]},{"id":189,"p":79,"en":"One, it's diverse.","zh":"第一，它是多样的。","s":766.04,"e":767.39,"w":[[766.16,766.3],[766.34,766.46],[766.54,767.14]]},{"id":190,"p":79,"en":"We think about the world in all the ways that we experience it.","zh":"我们用体验世界的所有方式来思考世界。","s":767.7,"e":770.02,"w":[[767.82,767.88],[767.96,768.12],[768.16,768.36],[768.38,768.44],[768.46,768.64],[768.66,768.72],[768.9,769.04],[769.06,769.12],[769.16,769.36],[769.38,769.46],[769.48,769.54],[769.58,770.04],[770.06,770.12]]},{"id":191,"p":79,"en":"We think visually, we think in sound, we think kinesthetically.","zh":"我们用视觉思考，用声音思考，用身体动作思考。","s":770.02,"e":772.95,"w":[[770.14,770.18],[770.22,770.36],[770.44,770.76],[770.9,770.96],[771.02,771.18],[771.22,771.28],[771.38,771.74],[771.78,771.84],[771.9,772.04],[772.08,772.7]]},{"id":192,"p":79,"en":"We think in abstract terms, we think in movement.","zh":"我们用抽象的方式思考，也用运动来思考。","s":773.55,"e":775.98,"w":[[773.67,773.73],[773.77,773.91],[773.95,774.01],[774.03,774.45],[774.49,774.83],[774.89,774.95],[775.05,775.23],[775.29,775.35],[775.39,775.73]]},{"id":193,"p":79,"en":"Secondly, intelligence is dynamic.","zh":"第二，智力是动态的。","s":776.47,"e":778.8,"w":[[776.59,777.03],[777.29,777.81],[777.83,777.93],[778.01,778.55]]},{"id":194,"p":79,"en":"If you look at the interactions of a human brain, as we heard yesterday from a number of presentations, intelligence is wonderfully interactive.","zh":"正如昨天几场演讲讲到的，如果你观察人脑内部的互动，就会发现智力的互动性非常奇妙。","s":779.61,"e":787.13,"w":[[779.73,779.83],[780.03,780.11],[780.11,780.23],[780.27,780.33],[780.39,780.45],[780.55,781.05],[781.07,781.13],[781.13,781.15],[781.19,781.39],[781.45,781.77],[781.87,781.97],[782.01,782.07],[782.11,782.25],[782.31,782.71],[782.83,782.99],[783.41,783.43],[783.53,783.71],[783.71,783.75],[783.77,784.47],[785.09,785.67],[785.87,785.97],[786.11,786.51],[786.53,787.09]]},{"id":195,"p":79,"en":"The brain isn't divided into compartments.","zh":"大脑并不是被分成一个个隔间的。","s":787.13,"e":789.17,"w":[[787.25,787.31],[787.33,787.55],[787.59,787.77],[787.79,788.12],[788.14,788.26],[788.3,788.92]]},{"id":196,"p":79,"en":"In fact, creativity -- which I define as the process of having original ideas that have value --","zh":"事实上，创造力——我把它定义为产生有价值的原创想法的过程——","s":789.82,"e":795.19,"w":[[789.94,790.0],[790.06,790.32],[790.66,791.22],[791.26,791.4],[791.58,791.6],[791.64,792.06],[792.14,792.2],[792.24,792.32],[792.34,792.7],[792.72,792.78],[792.82,793.1],[793.14,793.5],[793.66,794.0],[794.2,794.32],[794.36,794.52],[794.56,794.94]]},{"id":197,"p":79,"en":"more often than not comes about through the interaction of different disciplinary ways of seeing things.","zh":"往往来自不同学科看问题方式之间的相互作用。","s":795.5,"e":800.93,"w":[[795.62,795.82],[795.86,796.04],[796.08,796.2],[796.26,796.58],[796.94,797.16],[797.18,797.42],[797.46,797.6],[797.6,797.68],[797.76,798.38],[798.74,798.82],[798.94,799.24],[799.28,799.76],[799.82,800.0],[800.04,800.12],[800.16,800.38],[800.42,800.68]]},{"id":198,"p":80,"en":"By the way, there's a shaft of nerves that joins the two halves of the brain, called the corpus callosum.","zh":"顺便说一句，有一束神经连接着大脑的两个半球，叫作胼胝体。","s":803.27,"e":806.95,"w":[[803.39,803.47],[803.51,803.57],[803.59,803.69],[804.25,804.41],[804.43,804.45],[804.51,804.73],[804.75,804.81],[804.85,805.07],[805.07,805.15],[805.19,805.43],[805.45,805.51],[805.51,805.61],[805.63,805.79],[805.79,805.83],[805.83,805.89],[805.89,806.07],[806.09,806.23],[806.23,806.29],[806.33,806.63],[806.67,807.05]]},{"id":199,"p":80,"en":"It's thicker in women.","zh":"女性的胼胝体更厚。","s":806.95,"e":808.16,"w":[[807.07,807.17],[807.25,807.51],[807.57,807.63],[807.69,807.91]]},{"id":200,"p":80,"en":"Following off from Helen yesterday, this is probably why women are better at multitasking.","zh":"接着昨天海伦讲的，这大概就是女性更擅长同时做多件事的原因。","s":809.41,"e":813.44,"w":[[809.53,809.75],[809.77,809.85],[809.95,810.07],[810.07,810.17],[810.17,810.49],[810.83,810.95],[810.97,811.05],[811.41,811.75],[811.79,811.93],[811.99,812.15],[812.17,812.23],[812.23,812.41],[812.41,812.47],[812.53,813.19]]},{"id":201,"p":80,"en":"Because you are, aren't you?","zh":"因为你们确实更擅长，对吧？","s":814.17,"e":815.99,"w":[[814.29,814.55],[814.57,814.65],[814.77,814.93],[815.87,816.01],[816.01,816.07]]},{"id":202,"p":80,"en":"There's a raft of research, but I know it from my personal life.","zh":"有一大堆研究，但我是从个人生活里知道的。","s":815.99,"e":819.29,"w":[[816.11,816.25],[816.27,816.29],[816.41,816.63],[816.65,816.71],[816.75,817.19],[817.82,817.9],[817.96,817.98],[817.98,818.08],[818.12,818.16],[818.16,818.26],[818.32,818.36],[818.42,818.78],[818.8,819.04]]},{"id":203,"p":80,"en":"If my wife is cooking a meal at home, which is not often ... thankfully.","zh":"如果我妻子在家做饭——谢天谢地，不常做……","s":819.82,"e":824.95,"w":[[819.94,820.0],[820.06,820.16],[820.22,820.4],[820.44,820.5],[820.54,820.78],[820.8,820.82],[820.86,821.0],[821.02,821.1],[821.12,821.36],[821.64,821.76],[821.8,821.88],[821.92,822.02],[822.1,822.3],[824.3,824.7]]},{"id":204,"p":82,"en":"No, she's good at some things.","zh":"不，她在某些事情上很拿手。","s":828.04,"e":829.16,"w":[[828.16,828.22],[828.28,828.42],[828.44,828.56],[828.56,828.62],[828.66,828.8],[828.8,828.96]]},{"id":205,"p":82,"en":"But if she's cooking, she's dealing with people on the phone, she's talking to the kids, she's painting the ceiling --","zh":"但如果她在做饭，她会一边打电话，一边跟孩子说话，一边刷天花板——","s":829.16,"e":833.98,"w":[[829.28,829.34],[829.36,829.42],[829.44,829.6],[829.64,829.92],[830.44,830.72],[830.88,831.1],[831.12,831.24],[831.26,831.44],[831.46,831.52],[831.52,831.6],[831.64,831.96],[832.0,832.14],[832.18,832.39],[832.39,832.43],[832.43,832.51],[832.53,832.81],[832.89,833.03],[833.07,833.31],[833.33,833.39],[833.43,833.73]]},{"id":206,"p":84,"en":"she's doing open-heart surgery over here.","zh":"一边还在这边做心脏手术。","s":834.11,"e":837.38,"w":[[834.23,834.41],[835.61,835.79],[835.85,836.03],[836.07,836.21],[836.29,836.65],[836.81,836.95],[836.97,837.13]]},{"id":207,"p":84,"en":"If I'm cooking, the door is shut, the kids are out, the phone's on the hook, if she comes in, I get annoyed.","zh":"如果是我做饭，门要关上，孩子要出去，电话要挂好，她要是进来，我就会烦。","s":837.97,"e":843.62,"w":[[838.09,838.17],[838.37,838.47],[838.53,838.85],[839.03,839.11],[839.15,839.33],[839.39,839.45],[839.51,839.75],[840.29,840.35],[840.41,840.61],[840.63,840.71],[840.79,840.99],[841.31,841.37],[841.41,841.65],[841.69,841.77],[841.79,841.85],[841.89,842.07],[842.19,842.25],[842.27,842.33],[842.39,842.57],[842.59,842.67],[842.75,842.77],[842.79,842.89],[842.93,843.37]]},{"id":208,"p":84,"en":"I say, \"Terry, please, I'm trying to fry an egg in here.\"","zh":"我说：“特里，拜托，我在这儿煎个鸡蛋呢。”","s":843.62,"e":847.06,"w":[[844.41,844.43],[844.45,844.55],[844.61,844.79],[844.89,845.39],[845.43,845.49],[845.53,845.71],[845.71,845.75],[845.79,845.95],[845.97,846.03],[846.09,846.19],[846.21,846.29],[846.31,846.81]]},{"id":209,"p":86,"en":"\"Give me a break.\"","zh":"“让我清静一下。”","s":848.02,"e":855.15,"w":[[854.26,854.4],[854.42,854.46],[854.54,854.56],[854.64,854.9]]},{"id":210,"p":88,"en":"Actually, do you know that old philosophical thing, \"If a tree falls in a forest, and nobody hears it, did it happen?\"","zh":"其实，你们知道那个古老的哲学问题吗：“如果一棵树在森林里倒下，没人听见，那它倒下了吗？”","s":857.94,"e":862.9,"w":[[858.06,858.3],[858.3,858.34],[858.34,858.4],[858.4,858.5],[858.5,858.86],[858.9,859.02],[859.04,859.52],[859.54,859.68],[859.7,859.76],[859.8,859.82],[859.9,860.1],[860.2,860.48],[860.76,860.86],[860.9,860.92],[861.06,861.38],[861.4,861.46],[861.48,861.67],[861.73,861.93],[861.99,862.05],[862.11,862.21],[862.25,862.33],[862.37,862.65]]},{"id":211,"p":88,"en":"Remember that old chestnut?","zh":"还记得那个老掉牙的问题吗？","s":863.15,"e":864.32,"w":[[863.27,863.45],[863.45,863.55],[863.59,863.71],[863.73,864.07]]},{"id":212,"p":88,"en":"I saw a great T-shirt recently, which said, \"If a man speaks his mind in a forest, and no woman hears him, is he still wrong?\"","zh":"我最近看到一件很棒的 T 恤，上面写着：“如果一个男人在森林里说出心里话，没有女人听见，他还是错的吗？”","s":864.41,"e":872.04,"w":[[864.53,864.55],[864.57,864.67],[864.69,864.71],[864.77,864.95],[865.01,865.03],[865.17,865.57],[865.93,866.23],[866.25,866.39],[866.41,866.65],[867.61,867.67],[867.71,867.73],[867.83,868.07],[868.29,868.53],[868.55,868.65],[868.69,868.91],[868.93,868.99],[869.01,869.03],[869.11,869.59],[869.75,869.91],[869.91,869.97],[870.09,870.27],[870.35,870.59],[870.63,870.75],[871.05,871.13],[871.15,871.19],[871.27,871.45],[871.49,871.79]]},{"id":213,"p":90,"en":"And the third thing about intelligence is, it's distinct.","zh":"关于智力的第三点是：它是独特的。","s":877.73,"e":883.13,"w":[[880.2,880.3],[880.32,880.38],[880.46,880.72],[880.8,880.94],[880.98,881.2],[881.24,881.78],[881.82,881.98],[882.14,882.3],[882.44,882.88]]},{"id":214,"p":90,"en":"I'm doing a new book at the moment called \"Epiphany,\" which is based on a series of interviews with people about how they discovered their talent.","zh":"我现在正在写一本新书，叫《顿悟》，它基于一系列访谈，讲人们如何发现自己的天赋。","s":883.3,"e":890.11,"w":[[884.74,884.82],[884.84,884.98],[884.98,885.0],[885.0,885.12],[885.14,885.26],[885.26,885.3],[885.32,885.38],[885.38,885.54],[885.54,885.7],[885.7,886.14],[886.34,886.5],[886.52,886.62],[887.04,887.3],[887.32,887.38],[887.4,887.42],[887.48,887.68],[887.68,887.72],[887.76,888.04],[888.06,888.16],[888.18,888.36],[888.38,888.58],[888.62,888.76],[888.8,888.9],[888.92,889.3],[889.32,889.44],[889.52,889.86]]},{"id":215,"p":90,"en":"I'm fascinated by how people got to be there.","zh":"我对人们是怎么走到那一步的非常着迷。","s":890.5,"e":892.46,"w":[[890.62,890.68],[890.76,891.1],[891.13,891.19],[891.23,891.33],[891.37,891.55],[891.61,891.73],[891.77,891.83],[891.87,891.93],[892.03,892.21]]},{"id":216,"p":90,"en":"It's really prompted by a conversation I had with a wonderful woman who maybe most people have never heard of, Gillian Lynne.","zh":"这本书其实源于我和一位很棒的女士的一次谈话，大多数人可能没听说过她：吉莉安·琳恩。","s":892.85,"e":897.85,"w":[[892.97,893.09],[893.15,893.33],[893.53,893.85],[893.87,893.97],[894.01,894.03],[894.09,894.53],[894.53,894.55],[894.59,894.69],[894.71,894.81],[894.83,894.85],[894.91,895.25],[895.29,895.47],[895.51,895.57],[895.75,895.93],[895.97,896.13],[896.15,896.29],[896.29,896.37],[896.37,896.51],[896.53,896.67],[896.73,896.77],[897.21,897.49],[897.57,897.77]]},{"id":217,"p":90,"en":"Have you heard of her?","zh":"你们听说过她吗？","s":897.85,"e":898.68,"w":[[897.97,898.07],[898.09,898.15],[898.17,898.27],[898.29,898.33],[898.35,898.43]]},{"id":218,"p":90,"en":"Some have.","zh":"有些人听说过。","s":899.51,"e":900.18,"w":[[899.63,899.77],[899.79,899.93]]},{"id":219,"p":90,"en":"She's a choreographer, and everybody knows her work.","zh":"她是一位编舞家，每个人都知道她的作品。","s":900.23,"e":901.99,"w":[[900.35,900.49],[900.51,900.53],[900.59,901.09],[901.11,901.19],[901.23,901.55],[901.57,901.77],[901.79,901.85],[901.89,902.07]]},{"id":220,"p":90,"en":"She did \"Cats\" and \"Phantom of the Opera.\"","zh":"她编过《猫》和《歌剧魅影》。","s":901.99,"e":904.59,"w":[[902.11,902.17],[902.21,902.31],[902.37,902.73],[903.91,903.99],[904.03,904.27],[904.27,904.31],[904.31,904.37],[904.43,904.63]]},{"id":221,"p":90,"en":"She's wonderful.","zh":"她非常了不起。","s":904.59,"e":905.31,"w":[[904.71,904.87],[904.91,905.23]]},{"id":222,"p":90,"en":"I used to be on the board of The Royal Ballet, as you can see.","zh":"我以前是英国皇家芭蕾舞团的董事，你们看得出来吧。","s":905.31,"e":908.79,"w":[[905.43,905.45],[905.45,905.53],[905.53,905.57],[905.57,905.63],[905.65,905.71],[905.73,905.79],[905.86,906.06],[906.08,906.12],[906.12,906.2],[906.2,906.36],[906.4,906.98],[907.08,908.14],[908.16,908.24],[908.26,908.36],[908.42,908.54]]},{"id":223,"p":92,"en":"Gillian and I had lunch one day.","zh":"有一天吉莉安和我一起吃午饭。","s":911.46,"e":912.32,"w":[[911.58,911.84],[911.84,911.9],[911.9,911.92],[911.92,912.02],[912.06,912.22],[912.24,912.32],[912.32,912.42]]},{"id":224,"p":92,"en":"I said, \"How did you get to be a dancer?\"","zh":"我问：“你是怎么成为舞蹈家的？”","s":912.32,"e":913.69,"w":[[912.44,912.46],[912.46,912.58],[912.6,912.66],[912.66,912.72],[912.72,912.78],[912.78,912.84],[912.86,912.9],[912.9,912.94],[913.0,913.02],[913.08,913.44]]},{"id":225,"p":92,"en":"It was interesting.","zh":"答案很有意思。","s":914.28,"e":914.82,"w":[[914.4,914.44],[914.46,914.54],[914.56,914.92]]},{"id":226,"p":92,"en":"When she was at school, she was really hopeless.","zh":"她上学时，表现真的很差。","s":914.82,"e":916.91,"w":[[914.94,915.04],[915.06,915.12],[915.16,915.24],[915.24,915.32],[915.4,915.68],[915.76,915.84],[915.88,915.96],[916.04,916.24],[916.3,916.66]]},{"id":227,"p":92,"en":"And the school, in the '30s, wrote to her parents and said, \"We think Gillian has a learning disorder.\"","zh":"那是上世纪 30 年代，学校写信给她父母说：“我们认为吉莉安有学习障碍。”","s":917.46,"e":922.36,"w":[[917.58,917.78],[918.22,918.3],[918.5,918.8],[918.92,918.96],[918.98,919.06],[919.08,919.42],[919.92,920.12],[920.12,920.16],[920.18,920.26],[920.28,920.52],[920.52,920.59],[920.59,920.67],[920.67,920.71],[920.75,920.89],[920.95,921.19],[921.23,921.35],[921.39,921.41],[921.45,921.69],[921.71,922.11]]},{"id":228,"p":92,"en":"She couldn't concentrate; she was fidgeting.","zh":"她无法集中注意力，总是坐立不安。","s":922.69,"e":924.19,"w":[[922.81,922.87],[922.87,923.09],[923.11,923.53],[923.53,923.59],[923.59,923.67],[923.73,924.07]]},{"id":229,"p":92,"en":"I think now they'd say she had ADHD.","zh":"我想现在的人会说她有多动症。","s":924.19,"e":926.06,"w":[[924.31,924.33],[924.35,924.49],[924.55,924.69],[924.73,924.87],[924.87,924.99],[925.01,925.09],[925.11,925.23],[925.35,925.81]]},{"id":230,"p":92,"en":"Wouldn't you?","zh":"你们不觉得吗？","s":927.13,"e":927.74,"w":[[927.25,927.43],[927.43,927.49]]},{"id":231,"p":92,"en":"But this was the 1930s, and ADHD hadn't been invented at this point.","zh":"但那是 20 世纪 30 年代，当时还没有“发明”多动症。","s":928.41,"e":931.83,"w":[[928.53,928.61],[928.63,928.73],[928.77,928.85],[928.87,928.93],[929.17,929.69],[929.83,930.05],[930.05,930.11],[930.11,930.19],[930.21,930.41],[930.41,930.53],[930.55,930.95],[931.33,931.39],[931.41,931.53],[931.57,931.75]]},{"id":232,"p":92,"en":"It wasn't an available condition.","zh":"那时还没有这种病可以诊断。","s":931.83,"e":934.04,"w":[[931.95,932.01],[932.77,932.99],[933.01,933.07],[933.09,933.41],[933.41,933.79]]},{"id":233,"p":94,"en":"People weren't aware they could have that.","zh":"人们不知道自己可以得这种病。","s":937.94,"e":939.39,"w":[[938.06,938.24],[938.28,938.44],[938.46,938.62],[938.62,938.72],[938.72,938.84],[938.86,938.98],[939.0,939.14]]},{"id":234,"p":96,"en":"Anyway, she went to see this specialist.","zh":"总之，她去看了一位专家。","s":942.44,"e":946.39,"w":[[942.56,942.76],[942.8,942.86],[943.28,943.42],[943.46,943.5],[943.56,943.68],[945.38,945.48],[945.54,946.14]]},{"id":235,"p":96,"en":"So, this oak-paneled room, and she was there with her mother, and she was led and sat on this chair at the end, and she sat on her hands for 20 minutes,","zh":"那是一间橡木镶板的房间，她和妈妈在那儿，她被带到房间尽头的椅子上坐下，她把手压在屁股底下坐了 20 分钟，","s":946.7,"e":953.91,"w":[[946.82,946.88],[946.94,947.04],[947.14,947.26],[947.34,947.66],[947.72,947.94],[948.2,948.3],[948.38,948.44],[948.5,948.6],[948.64,948.84],[949.3,949.42],[949.44,949.52],[949.58,949.8],[949.86,949.96],[950.0,950.09],[950.49,950.59],[950.65,950.79],[950.81,950.91],[950.97,951.15],[951.19,951.25],[951.29,951.43],[951.93,952.17],[952.19,952.25],[952.27,952.33],[952.37,952.51],[952.55,952.63],[952.65,952.73],[952.85,953.01],[953.03,953.09],[953.11,953.17],[953.19,953.43],[953.45,953.53],[953.57,953.79],[953.81,954.01]]},{"id":236,"p":96,"en":"while this man talked to her mother about all the problems Gillian was having at school, because she was disturbing people, her homework was always late, and so on.","zh":"这位医生和她妈妈谈着吉莉安在学校遇到的种种问题：她打扰别人，作业总是迟交，等等。","s":953.91,"e":961.71,"w":[[954.03,954.19],[954.19,954.29],[954.33,954.47],[954.55,954.79],[954.79,954.83],[954.83,954.89],[954.91,955.07],[955.09,955.29],[955.35,955.43],[955.43,955.51],[955.53,955.79],[955.83,956.05],[956.07,956.15],[956.19,956.43],[956.43,956.51],[956.55,956.77],[959.35,959.55],[959.55,959.61],[959.61,959.69],[959.71,960.17],[960.19,960.41],[960.45,960.51],[960.65,960.95],[960.99,961.09],[961.11,961.29],[961.33,961.51],[961.53,961.61],[961.63,961.69],[961.75,961.79]]},{"id":237,"p":96,"en":"Little kid of eight.","zh":"一个八岁的小孩。","s":961.71,"e":962.58,"w":[[961.83,961.99],[962.01,962.13],[962.13,962.19],[962.23,962.33]]},{"id":238,"p":96,"en":"In the end, the doctor went and sat next to Gillian and said, \"I've listened to all these things your mother's told me.","zh":"最后，医生走过去坐在吉莉安旁边说：“你妈妈告诉我的这些事，我都听到了。","s":962.71,"e":968.44,"w":[[962.83,962.89],[962.93,962.99],[963.03,963.21],[965.28,965.36],[965.4,965.64],[965.66,965.78],[965.78,965.84],[965.86,965.98],[966.02,966.12],[966.14,966.18],[966.2,966.38],[966.38,966.44],[966.44,966.56],[966.72,966.9],[966.92,967.12],[967.14,967.18],[967.2,967.3],[967.3,967.44],[967.46,967.66],[967.74,967.82],[967.82,968.02],[968.06,968.28],[968.32,968.38]]},{"id":239,"p":96,"en":"I need to speak to her privately.","zh":"我需要和她单独谈谈。","s":968.44,"e":969.83,"w":[[968.56,968.58],[968.58,968.72],[968.76,968.8],[968.84,969.0],[969.02,969.06],[969.08,969.16],[969.18,969.58]]},{"id":240,"p":96,"en":"Wait here.","zh":"在这儿等着。","s":972.24,"e":972.72,"w":[[972.36,972.5],[972.56,972.72]]},{"id":241,"p":96,"en":"We'll be back.","zh":"我们会回来的。","s":972.72,"e":973.22,"w":[[972.84,972.98],[973.0,973.06],[973.12,973.3]]},{"id":242,"p":96,"en":"We won't be very long,\" and they went and left her.","zh":"不会太久。”说完他们就出去了，留下她一个人。","s":973.22,"e":975.85,"w":[[973.34,973.38],[973.42,973.52],[973.52,973.56],[973.6,973.74],[973.78,974.0],[974.94,975.02],[975.02,975.1],[975.1,975.24],[975.26,975.34],[975.36,975.52],[975.52,975.6]]},{"id":243,"p":97,"en":"But as they went out of the room, he turned on the radio that was sitting on his desk.","zh":"但他们走出房间时，医生打开了桌上的收音机。","s":975.92,"e":979.71,"w":[[976.04,976.12],[976.16,976.24],[976.26,976.34],[976.36,976.5],[976.54,976.62],[976.62,976.66],[976.66,976.72],[976.78,977.0],[977.12,977.18],[977.28,977.5],[977.52,977.58],[977.6,977.68],[977.74,978.06],[978.28,978.36],[978.4,978.48],[978.52,978.78],[978.92,978.98],[979.0,979.1],[979.14,979.46]]},{"id":244,"p":97,"en":"And when they got out of the room, he said to her mother, \"Just stand and watch her.\"","zh":"出了房间后，他对她妈妈说：“就站在这儿看着她。”","s":980.51,"e":983.08,"w":[[980.63,980.69],[980.71,980.81],[980.83,980.91],[980.93,981.05],[981.07,981.19],[981.19,981.23],[981.23,981.29],[981.33,981.51],[981.55,981.61],[981.67,981.79],[981.81,981.85],[981.85,981.91],[981.93,982.07],[982.09,982.23],[982.25,982.43],[982.45,982.53],[982.55,982.75],[982.77,982.83]]},{"id":245,"p":97,"en":"And the minute they left the room, she was on her feet, moving to the music.","zh":"他们一离开房间，她就站起来，随着音乐动了起来。","s":983.91,"e":989.2,"w":[[984.03,984.25],[985.05,985.11],[985.15,985.33],[985.33,985.43],[985.47,985.63],[985.65,985.73],[985.77,985.97],[987.39,987.61],[987.63,987.71],[987.73,987.79],[987.81,987.89],[987.93,988.11],[988.27,988.53],[988.53,988.59],[988.59,988.67],[988.67,988.95]]},{"id":246,"p":97,"en":"And they watched for a few minutes, and he turned to her mother and said, \"Mrs. Lynne, Gillian isn't sick.","zh":"他们看了几分钟，医生转身对她妈妈说：“琳恩太太，吉莉安没有病。","s":989.73,"e":995.07,"w":[[989.85,989.93],[989.93,990.05],[990.05,990.21],[990.21,990.27],[990.29,990.31],[990.31,990.43],[990.47,990.75],[990.81,990.93],[990.97,991.03],[991.11,991.31],[991.33,991.39],[991.39,991.47],[991.49,991.71],[992.37,992.43],[992.49,992.61],[992.79,993.01],[993.07,993.29],[993.93,994.19],[994.28,994.48],[994.58,994.82]]},{"id":247,"p":97,"en":"She's a dancer.","zh":"她是个舞者。","s":995.26,"e":996.21,"w":[[995.38,995.54],[995.56,995.58],[995.62,995.96]]},{"id":248,"p":97,"en":"Take her to a dance school.\"","zh":"带她去舞蹈学校吧。”","s":998.26,"e":999.45,"w":[[998.38,998.54],[998.54,998.6],[998.62,998.66],[998.7,998.72],[998.74,998.98],[999.0,999.2]]},{"id":249,"p":98,"en":"I said, \"What happened?\"","zh":"我问：“后来呢？”","s":999.76,"e":1000.38,"w":[[999.88,999.9],[999.92,1000.04],[1000.04,1000.14],[1000.18,1000.46]]},{"id":250,"p":98,"en":"She said, \"She did.","zh":"她说：“她真的去了。","s":1000.38,"e":1001.69,"w":[[1000.5,1000.98],[1000.98,1001.1],[1001.14,1001.22],[1001.26,1001.44]]},{"id":251,"p":98,"en":"I can't tell you how wonderful it was.","zh":"我没法告诉你那有多美妙。","s":1002.26,"e":1003.68,"w":[[1002.38,1002.4],[1002.42,1002.62],[1002.66,1002.8],[1002.8,1002.86],[1002.98,1003.06],[1003.12,1003.46],[1003.48,1003.52],[1003.56,1003.72]]},{"id":252,"p":98,"en":"We walked in this room, and it was full of people like me -- people who couldn't sit still, people who had to move to think.\"","zh":"我们走进那个房间，里面全是像我一样的人——坐不住的人，必须动起来才能思考的人。”","s":1003.68,"e":1011.64,"w":[[1003.8,1003.84],[1003.9,1004.12],[1004.16,1004.2],[1004.22,1004.34],[1004.4,1004.58],[1004.98,1005.06],[1005.08,1005.12],[1005.14,1005.24],[1005.28,1005.42],[1005.44,1005.48],[1005.52,1005.74],[1005.78,1005.94],[1005.96,1006.04],[1006.88,1007.16],[1007.48,1007.54],[1007.62,1007.9],[1007.96,1008.1],[1008.16,1008.4],[1009.15,1009.43],[1009.63,1009.71],[1009.77,1009.93],[1010.01,1010.07],[1010.21,1010.59],[1010.99,1011.07],[1011.17,1011.39]]},{"id":253,"p":98,"en":"Who had to move to think.","zh":"必须动起来才能思考。","s":1011.95,"e":1013.56,"w":[[1012.07,1012.13],[1012.17,1012.31],[1012.37,1012.41],[1012.51,1012.79],[1012.97,1013.05],[1013.11,1013.31]]},{"id":254,"p":98,"en":"They did ballet, they did tap, jazz; they did modern; they did contemporary.","zh":"他们跳芭蕾、跳踢踏、跳爵士，跳现代舞，跳当代舞。","s":1013.79,"e":1017.39,"w":[[1013.91,1014.01],[1014.03,1014.13],[1014.19,1014.51],[1014.81,1014.91],[1014.91,1015.03],[1015.09,1015.35],[1015.77,1016.11],[1016.15,1016.25],[1016.25,1016.35],[1016.43,1016.67],[1016.69,1016.77],[1016.77,1016.83],[1016.83,1017.19]]},{"id":255,"p":98,"en":"She was eventually auditioned for the Royal Ballet School.","zh":"后来她去参加了皇家芭蕾舞学校的面试。","s":1017.39,"e":1019.46,"w":[[1017.51,1017.57],[1017.61,1017.67],[1017.67,1018.01],[1018.01,1018.37],[1018.37,1018.43],[1018.43,1018.49],[1018.51,1018.65],[1018.69,1018.93],[1018.99,1019.21]]},{"id":256,"p":98,"en":"She became a soloist; she had a wonderful career at the Royal Ballet.","zh":"她成了独舞演员，在皇家芭蕾舞团有过精彩的职业生涯。","s":1019.89,"e":1022.44,"w":[[1020.01,1020.07],[1020.11,1020.31],[1020.33,1020.35],[1020.41,1020.77],[1020.77,1020.83],[1020.83,1020.93],[1020.95,1020.97],[1021.07,1021.39],[1021.43,1021.59],[1021.61,1021.65],[1021.67,1021.75],[1021.77,1021.93],[1021.95,1022.19]]},{"id":257,"p":98,"en":"She eventually graduated from the Royal Ballet School, founded the Gillian Lynne Dance Company, met Andrew Lloyd Webber.","zh":"她最终从皇家芭蕾舞学校毕业，创办了吉莉安·琳恩舞蹈团，认识了安德鲁·劳埃德·韦伯。","s":1022.69,"e":1029.08,"w":[[1022.81,1022.87],[1022.91,1023.23],[1023.27,1023.68],[1023.68,1023.78],[1023.78,1023.86],[1023.88,1024.04],[1024.08,1024.3],[1024.34,1024.56],[1025.08,1026.18],[1026.24,1026.3],[1026.32,1026.58],[1026.64,1026.78],[1026.78,1027.02],[1027.06,1027.34],[1027.98,1028.12],[1028.18,1028.38],[1028.38,1028.58],[1028.62,1028.84]]},{"id":258,"p":98,"en":"She's been responsible for some of the most successful musical theater productions in history, she's given pleasure to millions, and she's a multimillionaire.","zh":"她参与创作了音乐剧史上一些最成功的作品，给数百万人带来了快乐，而且她是个千万富翁。","s":1029.08,"e":1034.93,"w":[[1029.2,1029.34],[1029.36,1029.48],[1029.52,1029.94],[1029.94,1030.0],[1030.02,1030.1],[1030.1,1030.14],[1030.14,1030.2],[1030.2,1030.28],[1030.28,1030.66],[1030.68,1030.94],[1030.96,1031.16],[1031.16,1031.46],[1031.48,1031.54],[1031.6,1031.96],[1032.48,1032.62],[1032.64,1032.78],[1032.82,1033.06],[1033.08,1033.14],[1033.18,1033.6],[1033.74,1033.82],[1033.84,1033.96],[1033.98,1034.0],[1034.06,1034.68]]},{"id":259,"p":98,"en":"Somebody else might have put her on medication and told her to calm down.","zh":"换了别人，可能会给她吃药，让她安静下来。","s":1035.66,"e":1039.1,"w":[[1035.78,1036.0],[1036.06,1036.34],[1036.5,1036.64],[1036.64,1036.72],[1036.76,1036.88],[1036.88,1036.94],[1036.94,1037.02],[1037.06,1037.62],[1037.98,1038.06],[1038.1,1038.26],[1038.26,1038.32],[1038.34,1038.38],[1038.43,1038.61],[1038.65,1038.85]]},{"id":260,"p":100,"en":"What I think it comes to is this: Al Gore spoke the other night about ecology and the revolution that was triggered by Rachel Carson.","zh":"我想，归根结底是这样：前几天晚上，阿尔·戈尔谈到了生态，以及蕾切尔·卡森引发的那场革命。","s":1041.28,"e":1056.41,"w":[[1048.75,1048.87],[1048.95,1048.97],[1048.99,1049.13],[1049.13,1049.19],[1049.21,1049.43],[1049.47,1049.53],[1049.57,1049.61],[1049.61,1049.81],[1050.05,1050.17],[1050.27,1050.47],[1050.51,1050.79],[1051.21,1051.27],[1051.29,1051.41],[1051.43,1051.65],[1051.79,1052.13],[1052.33,1052.81],[1053.07,1053.18],[1053.2,1053.28],[1053.32,1053.78],[1053.82,1053.9],[1053.92,1054.02],[1054.1,1054.4],[1055.22,1055.38],[1055.48,1055.76],[1055.8,1056.16]]},{"id":261,"p":100,"en":"I believe our only hope for the future is to adopt a new conception of human ecology, one in which we start to reconstitute our conception of the richness of human capacity.","zh":"我相信，我们对未来唯一的希望，是接受一种新的人类生态观：重新构建我们对人类能力之丰富的认识。","s":1057.3,"e":1067.53,"w":[[1057.42,1057.44],[1057.5,1057.78],[1057.82,1057.92],[1057.96,1058.1],[1058.16,1058.3],[1058.32,1058.4],[1058.4,1058.46],[1058.5,1058.86],[1059.46,1059.6],[1059.7,1059.8],[1060.36,1060.7],[1060.86,1060.88],[1061.0,1061.12],[1061.18,1061.68],[1061.76,1061.84],[1061.9,1062.16],[1062.2,1062.6],[1063.42,1063.52],[1063.56,1063.62],[1063.68,1063.9],[1064.04,1064.1],[1064.18,1064.4],[1064.44,1064.5],[1064.54,1065.06],[1065.1,1065.18],[1065.22,1065.64],[1065.64,1065.7],[1065.7,1065.78],[1065.82,1066.14],[1066.18,1066.26],[1066.3,1066.54],[1066.82,1067.28]]},{"id":262,"p":100,"en":"Our education system has mined our minds in the way that we strip-mine the earth for a particular commodity.","zh":"我们的教育体系开采我们的头脑，就像我们为了某种商品而对地球进行露天开采一样。","s":1068.13,"e":1074.92,"w":[[1068.25,1068.31],[1068.35,1068.81],[1068.87,1069.15],[1069.55,1069.71],[1069.91,1070.35],[1070.71,1070.83],[1070.91,1071.41],[1071.63,1071.71],[1071.73,1071.81],[1071.85,1071.99],[1072.05,1072.15],[1072.19,1072.25],[1072.39,1072.59],[1072.69,1072.87],[1072.91,1072.97],[1073.05,1073.31],[1073.61,1073.69],[1073.71,1073.73],[1073.75,1074.21],[1074.25,1074.67]]},{"id":263,"p":100,"en":"And for the future, it won't serve us.","zh":"面向未来，这样做对我们没有好处。","s":1075.35,"e":1077.54,"w":[[1075.47,1075.53],[1075.55,1075.65],[1075.67,1075.73],[1075.77,1076.13],[1076.45,1076.53],[1076.61,1076.83],[1076.93,1077.17],[1077.17,1077.29]]},{"id":264,"p":100,"en":"We have to rethink the fundamental principles on which we're educating our children.","zh":"我们必须重新思考教育孩子的根本原则。","s":1077.81,"e":1081.15,"w":[[1077.93,1077.99],[1078.03,1078.15],[1078.17,1078.23],[1078.35,1078.71],[1078.75,1078.81],[1078.91,1079.39],[1079.47,1079.85],[1079.89,1079.95],[1080.01,1080.11],[1080.13,1080.29],[1080.31,1080.73],[1080.77,1080.87],[1080.91,1081.25]]},{"id":265,"p":101,"en":"There was a wonderful quote by Jonas Salk, who said, \"If all the insects were to disappear from the Earth, within 50 years, all life on Earth would end.","zh":"乔纳斯·索尔克有句很精彩的话：“如果所有昆虫都从地球上消失，50 年内，地球上的所有生命都会终结。","s":1081.15,"e":1092.63,"w":[[1081.27,1082.23],[1082.23,1082.29],[1082.31,1082.33],[1082.39,1082.68],[1082.72,1082.92],[1082.94,1083.04],[1083.1,1083.38],[1083.44,1083.68],[1083.84,1083.9],[1084.02,1084.3],[1086.28,1086.36],[1086.44,1086.58],[1086.62,1086.72],[1087.12,1087.54],[1087.56,1087.66],[1087.68,1087.72],[1087.76,1088.18],[1088.2,1088.32],[1088.36,1088.44],[1088.52,1088.8],[1090.12,1090.34],[1090.42,1090.68],[1090.7,1090.92],[1091.08,1091.2],[1091.26,1091.48],[1091.5,1091.58],[1091.68,1091.88],[1091.94,1092.08],[1092.16,1092.38]]},{"id":266,"p":101,"en":"If all human beings disappeared from the Earth, within 50 years, all forms of life would flourish.\"","zh":"如果所有人类都从地球上消失，50 年内，所有生命形式都会繁荣起来。”","s":1093.7,"e":1099.34,"w":[[1093.82,1093.9],[1093.98,1094.1],[1094.18,1094.42],[1094.52,1094.84],[1094.88,1095.3],[1095.32,1095.44],[1095.44,1095.52],[1095.58,1095.84],[1096.92,1097.1],[1097.14,1097.39],[1097.41,1097.55],[1097.69,1097.81],[1097.87,1098.11],[1098.15,1098.21],[1098.27,1098.47],[1098.49,1098.63],[1098.69,1099.09]]},{"id":267,"p":101,"en":"And he's right.","zh":"他说得对。","s":1100.43,"e":1101.36,"w":[[1100.55,1100.63],[1100.65,1100.79],[1100.87,1101.11]]},{"id":268,"p":102,"en":"What TED celebrates is the gift of the human imagination.","zh":"TED 所颂扬的，是人类想象力这份礼物。","s":1102.35,"e":1106.04,"w":[[1102.47,1102.63],[1102.75,1103.01],[1103.11,1103.69],[1104.17,1104.27],[1104.31,1104.39],[1104.45,1104.67],[1104.71,1104.77],[1104.81,1104.89],[1104.93,1105.15],[1105.19,1105.79]]},{"id":269,"p":102,"en":"We have to be careful now that we use this gift wisely, and that we avert some of the scenarios that we've talked about.","zh":"现在我们必须小心，明智地使用这份礼物，避免我们谈到过的一些糟糕局面。","s":1106.49,"e":1113.92,"w":[[1106.61,1106.69],[1106.81,1106.97],[1107.01,1107.09],[1107.13,1107.23],[1107.61,1107.97],[1108.03,1108.25],[1108.71,1108.81],[1108.85,1108.91],[1109.01,1109.15],[1109.17,1109.31],[1109.37,1109.57],[1109.71,1110.17],[1110.85,1110.93],[1110.95,1111.05],[1111.07,1111.15],[1111.19,1111.59],[1112.06,1112.3],[1112.52,1112.6],[1112.64,1112.72],[1112.74,1113.16],[1113.18,1113.28],[1113.3,1113.48],[1113.52,1113.76],[1113.78,1114.02]]},{"id":270,"p":102,"en":"And the only way we'll do it is by seeing our creative capacities for the richness they are and seeing our children for the hope that they are.","zh":"而唯一的办法，就是看到我们的创造力有多么丰富，看到我们的孩子承载着多大的希望。","s":1113.92,"e":1122.37,"w":[[1114.04,1114.16],[1114.16,1114.24],[1114.36,1114.54],[1114.58,1114.7],[1114.72,1114.84],[1114.86,1114.92],[1115.02,1115.1],[1115.58,1115.66],[1115.74,1115.9],[1116.04,1116.3],[1116.42,1116.54],[1116.6,1116.94],[1116.96,1117.6],[1117.86,1117.94],[1117.98,1118.04],[1118.08,1118.4],[1118.44,1118.58],[1118.76,1118.96],[1119.66,1119.78],[1119.84,1120.04],[1120.1,1120.2],[1120.28,1120.66],[1121.14,1121.26],[1121.3,1121.36],[1121.44,1121.64],[1121.68,1121.78],[1121.8,1121.9],[1121.98,1122.12]]},{"id":271,"p":102,"en":"And our task is to educate their whole being, so they can face this future.","zh":"我们的任务是教育他们整个人，让他们能够面对这个未来。","s":1122.76,"e":1126.3,"w":[[1122.88,1122.96],[1123.0,1123.12],[1123.18,1123.52],[1123.56,1123.62],[1123.64,1123.7],[1123.8,1124.12],[1124.14,1124.28],[1124.34,1124.6],[1124.64,1124.92],[1125.34,1125.4],[1125.48,1125.58],[1125.6,1125.72],[1125.76,1125.98],[1126.0,1126.1],[1126.14,1126.4]]},{"id":272,"p":102,"en":"By the way -- we may not see this future, but they will.","zh":"顺便说一句——我们也许看不到这个未来，但他们会看到。","s":1126.3,"e":1130.12,"w":[[1126.42,1126.54],[1126.58,1126.66],[1126.68,1126.85],[1127.19,1127.27],[1127.33,1127.43],[1127.49,1127.61],[1127.71,1127.83],[1127.87,1127.99],[1128.03,1128.37],[1129.25,1129.35],[1129.43,1129.57],[1129.67,1129.87]]},{"id":273,"p":102,"en":"And our job is to help them make something of it.","zh":"而我们的工作，就是帮助他们有所作为。","s":1130.77,"e":1133.18,"w":[[1130.89,1130.99],[1131.03,1131.13],[1131.19,1131.43],[1131.71,1131.79],[1131.81,1131.85],[1131.87,1132.01],[1132.05,1132.15],[1132.21,1132.39],[1132.43,1132.69],[1132.71,1132.79],[1132.83,1132.93]]},{"id":274,"p":103,"en":"Thank you very much.","zh":"非常感谢大家。","s":1133.57,"e":1134.48,"w":[[1133.69,1133.83],[1133.85,1133.91],[1133.93,1134.05],[1134.07,1134.23]]}]};